/* ÉQUIPIER INCENDIE — fichier 5 : Sécuriser (risques, explosimétrie, gaz) ; PAO, déblai et fin d’intervention */
var INC8 = 'Incendie 8 — Sécuriser : risques, explosimétrie, gaz';
var INC9 = 'Incendie 9 — PAO, déblai et fin d’intervention';
var L5 = 'Livret stagiaire Équipier incendie SDIS 51 (v2019)';

/* ================================================================ 1. Sécuriser la zone */
VSAV.chap({
  id: 'inc-securiser-zone', part: 'inc', seq: INC8,
  title: 'Sécuriser la zone d’intervention : énergies, fluides, mesures conservatoires', short: 'Sécuriser la zone', motif: 'shield',
  sources: [L5 + ', Partie 1 (référentiel : « Sécuriser la zone d’intervention »)', 'Guide d’instruction et de manœuvre INC — MGO : réactions immédiates, coupure des énergies, les fluides', 'GDO Incendies de structures (2018), § 4.8 et 4.9, p. 43', 'Diaporama « Les fuites de gaz » (SDIS 51)'],
  summary: 'Identifier vite les dangers (gaz, électricité, eau), couper les énergies sans jamais les rétablir et se protéger soi-même.',
  why: '<b>Pourquoi couper les énergies si tôt ?</b> Le gaz et l’électricité sont les <b>principaux risques pour les intervenants</b> : la coupure supprime d’un coup le risque d’électrocution et celui d’explosion. Ces actions font partie des <b>réactions immédiates</b> : elles sont lancées dès l’arrivée, parfois avant la fin de la reconnaissance, parce qu’attendre expose le binôme.',
  sections: [
    { id: 'risques', t: 'Les risques à identifier', ic: 'alert', src: L5 + ', Partie 1, objectif 3 « Sécuriser la zone d’intervention » ; GDO 2018 § 4.8-4.9, p. 43',
      html: '<p>Le référentiel de l’équipier incendie liste les risques à reconnaître et les actions adaptées : <b>gaz, risque chimique (RCH), radiologique (RAD), explosion, électrique, effondrement, voies ferrées, photovoltaïque</b>. Il y associe l’explosimétrie, la coupure des fluides, les premières mesures conservatoires, l’autoprotection, puis le déblai, la préservation des traces et indices et la surveillance (voir les chapitres suivants).</p>' +
        '<p>Le GDO rappelle que le risque électrique est <b>partout</b> et qu’il est sournois : les branchements sont parfois <b>non réglementaires, doubles ou temporaires</b>. Même après la coupure principale, il faut donc <b>rester attentif</b>. Il menace :</p>' +
        '<ul class="check"><li>sur la voie publique, au positionnement des engins (échelles à main, MEA, lignes ferroviaires, tramway) ;</li><li>dans les structures, le long du cheminement (câblage, installations particulières comme les panneaux photovoltaïques) ;</li><li>lors de l’utilisation des lances et de l’eau en général ;</li><li>pendant le déblai, notamment lors du dégarnissage.</li></ul>' +
        '<p>Selon l’activité du bâtiment, d’autres risques sont à rechercher : gaz (de ville, en bouteille, réseau local), fluides industriels…</p>' },
    { id: 'reactions', t: 'Premières mesures : les réactions immédiates', ic: 'clock', src: 'Guide d’instruction et de manœuvre INC — MGO, « Arrivée sur les lieux » et « Réactions immédiates »',
      html: '<p>À l’arrivée, le chef d’agrès questionne le requérant. Parmi les questions types figurent : <i>« Avez-vous le gaz ? Où se trouve la coupure ? Où se situe la coupure électrique ? »</i></p>' +
        '<p>Les <b>réactions immédiates</b> sont les actions que le COS entreprend dès son arrivée ; elles précèdent le raisonnement tactique :</p>' +
        '<div class="tw"><table><tbody><tr><td>Sauvetages et mises en sécurité</td><td>Évacuations (verticale, horizontale, extérieure)</td></tr><tr><td>Confinement, mise à l’abri</td><td>Périmètre de sécurité</td></tr><tr><td>Prise de renseignements</td><td>Protection</td></tr><tr><td>Stopper les propagations (action sur sources, flux, cibles)</td><td><b>Coupure des fluides et énergies</b></td></tr><tr><td colspan="2">Message d’ambiance (demande de renfort)</td></tr></tbody></table></div>' +
        '<p>Exemple de message d’ambiance du guide : le chef d’agrès y demande notamment <b>« ERDF, GRDF »</b> : les gestionnaires de réseau sont appelés tôt pour sécuriser durablement les installations.</p>' },
    { id: 'energies', t: 'Couper le gaz et l’électricité', ic: 'bolt', src: 'Guide d’instruction et de manœuvre INC — MGO, « Coupure des énergies »',
      html: '<p>Une des premières actions est la <b>coupure des énergies sur la zone concernée</b> (bâtiment, étage, volume…), principalement le gaz et l’électricité. Elles doivent être identifiées rapidement et une action de coupure entreprise.</p>' +
        '<div class="callout bad"><b>Les sapeurs-pompiers ne doivent en aucun cas rétablir les énergies coupées.</b></div>' +
        '<p><b>Électricité dans les pavillons</b> (guide) :</p><ul class="check"><li>À l’intérieur de l’habitation, le <b>disjoncteur différentiel principal</b> : c’est lui qu’il faut <b>privilégier</b>. Il existe aussi des différentiels secondaires (pouvant alimenter à eux seuls une pièce par exemple).</li><li>Le guide cite aussi un coffret sur voie publique ouvrable avec la polycoise (disjoncteur de branchement, cas d’un pavillon situé à plus de 30 m de la rue) : <b>à ne manipuler que sur ordre</b>, s’il existe un coffret de 50 cm × 50 cm contenant un organe de coupure.</li></ul>' +
        '<p><b>Gaz :</b> l’action de fermeture se nomme <b>« barrer »</b> ; en général les conduites sont peintes en <b>jaune</b>. Les organes que le sapeur-pompier peut ou non manœuvrer sont détaillés dans le chapitre « Les fuites de gaz ».</p>' },
    { id: 'fluides', t: 'Les autres fluides : eau, fluides médicaux', ic: 'drop', src: 'Guide d’instruction et de manœuvre INC — MGO, « Les fluides »',
      html: '<p><b>L’eau</b> se coupe, du plus général au plus local, par :</p><ul class="check"><li>l’organe de coupure général ;</li><li>le robinet de pied de colonne montante ;</li><li>le robinet de branchement de particulier ;</li><li>le robinet de compteur.</li></ul>' +
        '<p>Le guide associe à une fuite d’eau les risques d’<b>électrisation, de dégâts, de surcharge et de gel</b>.</p>' +
        '<p><b>Établissements de soins et installations :</b> certains liquides ou gaz sont repérables par un <b>code couleur</b>. Les vannes de sectionnement des fluides médicaux ne se manœuvrent que par une <b>action réfléchie, en concertation avec le personnel présent</b> (un patient peut dépendre de l’oxygène distribué).</p>' },
    { id: 'autoprotection', t: 'Autoprotection', ic: 'shield', src: L5 + ', § 7.1.2 et § 7.3 ; diaporama « Les fuites de gaz » ; Guide d’instruction INC — placement des engins',
      html: '<p>L’autoprotection reprend des règles communes à tous les risques de ce chapitre :</p><ul class="check"><li><b>EPI complets</b> adaptés au risque (tenue de feu complète, ARI…).</li><li><b>Engagement d’un minimum de personnel</b> et limitation des actions au strict nécessaire (sauvetages, reconnaissances strictement nécessaires).</li><li><b>Approche adaptée</b> : sur fuite de gaz, l’engin ne dépasse pas l’adresse (50 m en amont, selon le guide) ; en risque chimique, rester dans la zone opposée au sens du vent ; près d’une ligne électrique, respecter les distances de sécurité.</li><li><b>Binôme</b> : contact permanent ; en risque chimique, pour tout binôme engagé, un binôme de sécurité doit être prêt à intervenir.</li><li><b>Dans le doute</b>, considérer une installation électrique comme sous tension et une atmosphère comme dangereuse tant que l’explosimètre n’a pas tout contrôlé.</li></ul>' }
  ],
  key: ['Gaz et électricité = principaux risques des intervenants : identifier et couper tôt.', 'Les SP ne rétablissent JAMAIS une énergie coupée.', 'Coupure électrique d’un pavillon : privilégier le disjoncteur différentiel principal intérieur.', 'Fermer le gaz se dit « barrer » ; conduites généralement peintes en jaune.', 'Eau : coupure générale, pied de colonne montante, branchement, compteur.', 'Fluides médicaux : coupure réfléchie, en concertation avec le personnel.'],
  traps: ['Croire qu’une coupure principale suffit : branchements doubles ou temporaires possibles (GDO).', 'Remettre le courant ou le gaz « pour rendre service » au sinistré : interdit.', 'Manipuler le coffret sur voie publique sans ordre.'],
  quiz: [
    { q: 'Après une intervention, le sinistré demande de rouvrir le gaz que vous avez coupé :', c: ['Refuser : les SP ne rétablissent jamais une énergie coupée', 'Rouvrir si l’explosimètre indique 0 %', 'Rouvrir sur ordre du chef d’équipe', 'Rouvrir après aération'], e: 'Le guide est formel : les SP ne doivent en aucun cas rétablir les énergies coupées. Le diaporama gaz ajoute que l’organe manœuvré ne doit jamais être rouvert et que l’agent GRDF est informé.', s: 'energies' },
    { q: 'Dans un pavillon, quel organe de coupure électrique le guide recommande-t-il de privilégier ?', c: ['Le disjoncteur différentiel principal à l’intérieur', 'Le coffret sur voie publique', 'Les différentiels de chaque pièce', 'Le compteur du voisin'], e: 'Le disjoncteur différentiel principal intérieur est à privilégier ; le coffret sur voie publique ne se manipule que sur ordre.', s: 'energies' },
    { q: 'Pourquoi rester vigilant même après la coupure électrique principale ?', c: ['Les branchements peuvent être non réglementaires, doubles ou temporaires', 'Le courant revient toujours après 10 minutes', 'La coupure ne concerne que l’éclairage', 'Ce n’est pas nécessaire'], e: 'GDO 2018 § 4.8 : les branchements sont quelquefois non réglementaires, doubles ou temporaires.', s: 'risques' },
    { q: 'Comment se nomme l’action de fermeture du gaz ?', c: ['Barrer', 'Consigner', 'Purger', 'Détendre'], e: 'Guide d’instruction INC : « l’action de fermeture se nomme barrer » ; conduites en général peintes en jaune.', s: 'energies' },
    { q: 'Les vannes de fluides médicaux d’un établissement de soins :', c: ['Se ferment de façon réfléchie, en concertation avec le personnel', 'Se ferment systématiquement dès l’arrivée', 'Ne concernent jamais les SP', 'Se ferment toujours en premier'], e: 'Le guide précise : action réfléchie en concertation avec le personnel présent.', s: 'fluides' },
    { q: 'La coupure des fluides et énergies fait partie :', c: ['Des réactions immédiates du COS à l’arrivée', 'Uniquement de la phase de déblai', 'Des missions exclusives de GRDF/ERDF', 'Du reconditionnement du matériel'], e: 'Le guide la classe parmi les réactions immédiates, qui précèdent le raisonnement tactique.', s: 'reactions' }
  ]
});

/* ================================================================ 2. Risque électrique */
VSAV.chap({
  id: 'inc-risque-electrique', part: 'inc', seq: INC8,
  title: 'Le risque électrique et les panneaux photovoltaïques', short: 'Risque électrique', motif: 'bolt',
  sources: [L5 + ', § 7.1 Le risque électrique, p. 106-111', 'GDO Incendies de structures (2018), § 4.8, p. 43'],
  summary: 'Électrisation, électrocution, domaines de tension, seuils d’intensité, conduite à tenir et distances de sécurité.',
  why: '<b>Pourquoi tant de règles ?</b> Le nombre d’accidents électriques diminue, mais ils sont <b>souvent très graves</b>. Le danger ne se voit pas, peut persister après la coupure (réenclenchement, tension résiduelle, induction) et l’eau des lances le transporte jusqu’au porte-lance. La seule vraie protection est l’<b>éloignement</b> et la <b>mise en sécurité de l’installation</b>.',
  sections: [
    { id: 'definitions', t: 'Définitions et facteurs', ic: 'book', src: L5 + ', § 7.1.1, p. 106-107',
      html: '<p>Le risque électrique comprend le <b>contact</b> (direct ou non) avec une pièce nue sous tension, le <b>court-circuit</b> et l’<b>arc électrique</b>. Conséquences : électrisation, électrocution, incendie, explosion.</p>' +
        '<div class="tw"><table><thead><tr><th>Terme</th><th>Définition (livret)</th></tr></thead><tbody><tr><td><b>Électrisation</b></td><td>Tout accident électrique, <b>mortel ou non</b> : d’une simple commotion à une fibrillation ventriculaire mortelle.</td></tr><tr><td><b>Électrocution</b></td><td>Accident <b>mortel</b> dû à l’électricité.</td></tr></tbody></table></div>' +
        '<p>Les effets du courant dépendent de l’<b>individu</b> (âge, poids, sexe, physiologie), de la <b>nature et de la durée</b> du passage (alternatif, continu…, moment par rapport au rythme cardiaque) et des <b>conditions de contact</b> (surface, peau sèche ou mouillée, trajet du courant entre points d’entrée et de sortie).</p>' +
        '<div class="tw"><table><thead><tr><th>Grandeur</th><th>Unité</th><th>Image hydraulique (livret)</th></tr></thead><tbody><tr><td>Tension</td><td>volt (V)</td><td>Pression de l’eau / hauteur de chute : plus elle est élevée, plus le risque est grand.</td></tr><tr><td>Intensité</td><td>ampère (A)</td><td>Débit d’un cours d’eau : plus il est grand, plus on risque d’être emporté.</td></tr><tr><td>Résistance</td><td>ohm (Ω)</td><td>Diamètre du tuyau : plus la résistance est faible, plus l’intensité augmente.</td></tr></tbody></table></div>' +
        '<div class="callout warn"><b>« L’intensité tue ; le voltage brûle. »</b> (livret)</div>' },
    { id: 'seuils', t: 'Domaines de tension et seuils d’intensité', ic: 'list', src: L5 + ', p. 108',
      html: '<div class="tw"><table><thead><tr><th>Domaine</th><th>Courant alternatif</th><th>Courant continu</th></tr></thead><tbody><tr><td>Très basse tension (TBT)</td><td>≤ 50 V</td><td>≤ 120 V</td></tr><tr><td>Basse tension A (BTA)</td><td>50 à 500 V</td><td>120 à 750 V</td></tr><tr><td>Basse tension B (BTB)</td><td>500 à 1 000 V</td><td>750 à 1 500 V</td></tr><tr><td>Haute tension A (HTA)</td><td>1 000 à 50 000 V</td><td>1 500 à 75 000 V</td></tr><tr><td>Haute tension B (HTB)</td><td>&gt; 50 000 V</td><td>&gt; 75 000 V</td></tr></tbody></table></div>' +
        '<div class="tw"><table><thead><tr><th>Intensité</th><th>Réaction du corps</th></tr></thead><tbody><tr><td>0,2 à 0,4 mA</td><td>Seuil de la sensation ou de perception</td></tr><tr><td>10 à 15 mA</td><td>Seuil de non lâché (tétanisation)</td></tr><tr><td>15 à 25 mA</td><td>Seuil de paralysie ventilatoire (asphyxie)</td></tr><tr><td>65 à 100 mA</td><td>Seuil de fibrillation cardiaque irréversible</td></tr><tr><td>1 A</td><td>Arrêt du cœur</td></tr></tbody></table></div>' +
        '<p><b>Risques associés :</b> brûlures (points d’entrée et de sortie, organes traversés, arc électrique), troubles du rythme cardiaque pouvant entraîner la mort, chute (depuis une échelle…) ou projection sous l’effet du choc, incendie.</p>',
      figs: [{ img: 'img/inc/5/tension-intensite.jpg', cap: 'Domaines de tension et réaction face à l’intensité', txt: '<p>En haut, les seuils des domaines de tension en alternatif (au-dessus de la barre) et en continu (en dessous). La pyramide montre qu’il suffit de quelques dizaines de milliampères pour bloquer la respiration ou le cœur.</p>', src: L5 + ', p. 108' }] },
    { id: 'intervention', t: 'Conduite à tenir en intervention', ic: 'shield', src: L5 + ', § 7.1.2, p. 109',
      html: '<ul class="check"><li><b>S’assurer de la coupure des énergies</b> lors des incendies (gaz, électricité).</li><li>Dans le doute, <b>toujours se dire que les installations électriques sont sous tension</b>.</li><li><b>Ne pas couper les câbles orange</b> (haute tension) des véhicules hybrides.</li><li><b>Appeler le responsable du réseau</b> pour la coupure de l’installation (consignation).</li><li>Réaliser un <b>périmètre de sécurité public</b>.</li><li>Attention au <b>contact ou à l’approche</b> (arc à distance) des câbles avec les mâts des engins, les échelles aériennes et les jets de lance (à positionner en <b>jet diffusé d’attaque</b>).</li><li><b>Limiter les actions au strict nécessaire</b> : sauvetage de vies humaines…</li><li>Se déplacer à <b>petits pas</b> (tension de pas) ; en progression, <b>avancer à tâtons avec le dos de la main</b>.</li><li>Se faire <b>guider par un tiers</b> lors d’une évolution à risques ; <b>ne pas marcher dans l’eau</b> près d’une source électrique.</li></ul>' +
        '<div class="callout bad"><b>Distances de sécurité :</b> <b>3 m</b> des câbles de moins de 50 000 V ; <b>5 m</b> si la tension est supérieure ou égale à 50 000 V.</div>' +
        '<p><b>Mesures générales de protection :</b> tenue de feu complète (casque avec lunettes ou protection du visage baissées, gants, cagoule) ; ne pas porter d’éléments conducteurs (bijoux, boucle de ceinture, téléphone…) ; utiliser les équipements disponibles (valises électro-secours, gants et bottes isolants…) ; redoubler de vigilance par brouillard, pluie ou fumées.</p>' },
    { id: 'pas', t: 'Tension de pas et dangers après coupure', ic: 'walk', src: L5 + ', p. 110',
      html: '<p>Plus les pieds sont <b>écartés</b>, plus la différence de potentiel entre eux est grande, donc plus le risque d’électrisation augmente : d’où les <b>petits pas</b>.</p>' +
        '<p><b>Même si le courant est interrompu</b>, restent possibles :</p><ul class="check"><li>un <b>réarmement automatique</b> de l’installation lors de la détection d’un problème ;</li><li>une <b>tension résiduelle</b> malgré la coupure ;</li><li>une <b>réalimentation</b> : toujours rester en contact avec le responsable du réseau tant que l’intervention n’est pas terminée ;</li><li>des phénomènes d’<b>induction</b> dus à des câbles sous tension voisins.</li></ul>',
      figs: [{ img: 'img/inc/5/tension-de-pas.jpg', cap: 'La tension de pas', txt: '<p>Pieds écartés : danger. Pieds rapprochés : la différence de potentiel est réduite.</p>', src: L5 + ', p. 110' }] },
    { id: 'ppv', t: 'Feu en présence de panneaux photovoltaïques', ic: 'sun', src: L5 + ', p. 111 (procédure opérationnelle SDIS 51 « Intervention feu en présence de panneaux photovoltaïques »)',
      html: '<div class="callout warn"><b>Divergence entre sources :</b> la procédure PPV (POP/02, livret p. 111) limite les extincteurs poudre, eau pulvérisée ou CO2 aux tensions ≤ 1 000 V ; le § 2.2 du livret indique que la poudre reste utilisable au-delà de 1 000 V et le CO2 sous 5 000 V. Sur un feu avec panneaux photovoltaïques, applique la procédure.</div><p><b>Risques :</b> électrisation, électrocution, chute de matériaux. <b>Sécurité du personnel :</b> EPI de feu pour tous, exposition minimum, distance maximale.</p>' +
        '<ul class="check"><li>Questionnement dirigé du propriétaire et/ou de l’exploitant ; identification de la présence de PPV ; rappel des risques à tout le personnel.</li><li>Couper les énergies des disjoncteurs <b>consommation ET production</b>, et la coupure pour intervention des secours si elle existe.</li><li>Reconnaissances aériennes : <b>privilégier les MEA</b> aux échelles à main (risque de contact direct ou indirect).</li></ul>' +
        '<div class="tw"><table><thead><tr><th>Extinction</th><th>Condition</th></tr></thead><tbody><tr><td>LDMRS 45 à 500 l/min en <b>jet diffusé d’attaque</b></td><td>À <b>plus de 3 m</b> de la source, avec <b>test en pulsing</b> au préalable</td></tr><tr><td>Extincteur poudre, eau pulvérisée ou CO<sub>2</sub></td><td>Si tension <b>&lt; 1 000 V</b> ; tenir à <b>plus de 50 cm</b> du foyer (risque de contact avec la lance)</td></tr></tbody></table></div>' +
        '<div class="callout warn">L’efficacité du <b>bâchage</b> des panneaux reste à démontrer : on n’y recourt <b>qu’après avis du COS</b>. Partenaires : ErDF, exploitant.</div>' }
  ],
  key: ['Électrisation = tout accident électrique ; électrocution = accident mortel.', '« L’intensité tue ; le voltage brûle. »', 'Distances : 3 m (< 50 000 V), 5 m (≥ 50 000 V).', 'Dans le doute, l’installation est sous tension.', 'Petits pas, dos de la main, jet diffusé d’attaque.', 'PPV : couper consommation ET production ; lance à plus de 3 m, test en pulsing.', 'Ne pas couper les câbles orange des véhicules hybrides.'],
  traps: ['Croire qu’après coupure tout danger est écarté (réarmement, tension résiduelle, induction).', 'Attaquer au jet droit près d’une installation électrique.', 'Sur un feu avec panneaux photovoltaïques, utiliser un extincteur à moins de 50 cm du foyer ou sur une tension supérieure à 1 000 V (procédure POP/02).'],
  quiz: [
    { q: 'Distance de sécurité vis-à-vis d’un câble de 20 000 V :', c: ['3 m', '1 m', '5 m', '10 m'], e: 'Livret p. 109 : 3 m des câbles de moins de 50 000 V ; 5 m au-delà.', s: 'intervention' },
    { q: 'Quel seuil d’intensité correspond au « non lâché » (tétanisation) ?', c: ['10 à 15 mA', '0,2 à 0,4 mA', '65 à 100 mA', '1 A'], e: 'Livret p. 108 : 10 à 15 mA = seuil de non lâché.', s: 'seuils' },
    { q: 'L’électrocution désigne :', c: ['Un accident électrique mortel', 'Tout accident électrique', 'Une brûlure par arc', 'Un choc sans conséquence'], e: 'L’électrisation désigne tout accident électrique, mortel ou non ; l’électrocution est l’accident mortel.', s: 'definitions' },
    { q: 'Pourquoi se déplacer à petits pas près d’une source électrique ?', c: ['Pour limiter la tension de pas', 'Pour économiser l’air de l’ARI', 'Pour ne pas glisser sur la mousse', 'Pour entendre les crépitements'], e: 'Pieds écartés = différence de potentiel plus grande = risque d’électrisation accru.', s: 'pas' },
    { q: 'Feu avec panneaux photovoltaïques : quels disjoncteurs couper ?', c: ['Consommation ET production', 'Consommation seulement', 'Production seulement', 'Aucun : attendre ErDF'], e: 'Procédure SDIS 51 citée p. 111 : couper les disjoncteurs consommation ET production.', s: 'ppv' },
    { q: 'Extinction d’un feu avec PPV à la lance :', c: ['LDMRS en jet diffusé d’attaque à plus de 3 m, après un test en pulsing', 'Jet droit au plus près', 'Mousse uniquement', 'Interdiction totale d’utiliser l’eau'], e: 'LDMRS 45 à 500 l/min en jet diffusé d’attaque à plus de 3 m, test en pulsing préalable.', s: 'ppv' },
    { q: 'Le courant a été coupé par le gestionnaire. Que retenir ?', c: ['Rester en contact avec lui : réarmement, tension résiduelle ou induction restent possibles', 'Tout danger est écarté', 'On peut marcher dans l’eau', 'On peut retirer les gants'], e: 'Livret p. 110 : même courant interrompu, ces phénomènes restent possibles.', s: 'pas' }
  ]
});

/* ================================================================ 3. Explosimétrie */
VSAV.chap({
  id: 'inc-explosimetrie', part: 'inc', seq: INC8,
  title: 'Notions d’explosimétrie et monoxyde de carbone', short: 'Explosimétrie', motif: 'blast',
  sources: [L5 + ', § 2.6 Notions d’explosimétrie, p. 48-51', 'Diaporama « Les fuites de gaz » (SDIS 51) : explosimétrie, CO, détecteur BW GasAlert MicroClip', 'Guide d’instruction et de manœuvre INC — le risque explosif'],
  summary: 'LIE, LSE, zone d’explosivité, fonctionnement et limites de l’explosimètre, seuils d’alarme et dangers du CO.',
  why: '<b>Pourquoi l’explosimètre ne dit pas « tout va bien » ?</b> Il ne mesure que de 0 à 100 % de la LIE, à l’endroit où il se trouve, pour un gaz étalon donné. Les poches de gaz se déplacent ; un mélange trop riche peut redevenir explosif en se diluant. Comprendre ces limites évite de croire une valeur rassurante au mauvais endroit.',
  sections: [
    { id: 'definitions', t: 'Explosion, explosibilité, explosivité', ic: 'book', src: L5 + ', § 2.6 § 1, p. 48 ; diaporama « Les fuites de gaz »',
      html: '<p>Une <b>explosion</b> est une combustion très vive, à grande vitesse de réaction :</p>' +
        '<div class="tw"><table><thead><tr><th>Type</th><th>Vitesse</th><th>Surpression (livret)</th></tr></thead><tbody><tr><td><b>Déflagration</b></td><td>Inférieure à la vitesse du son</td><td>4 à 10 bars</td></tr><tr><td><b>Détonation</b></td><td>Supérieure à la vitesse du son</td><td>20 à 30 bars</td></tr></tbody></table></div>' +
        '<ul class="check"><li><b>Atmosphère explosible</b> : présence d’un gaz inflammable et d’un comburant, mais pas forcément dans les bonnes proportions.</li><li><b>Atmosphère explosive</b> : gaz inflammable et comburant <b>dans des proportions données</b> ; en présence d’une source d’ignition ou de chaleur, combustion très vive.</li></ul>' +
        '<p class="small muted">Le diaporama définit l’atmosphère explosible par la seule « présence d’un gaz inflammable » ; le livret y ajoute le comburant. Le sens opérationnel est le même.</p>' },
    { id: 'limites', t: 'LIE, LSE et zone d’explosivité', ic: 'target', src: L5 + ', § 2.6 § 2, p. 48-50 ; diaporama « Les fuites de gaz »',
      html: '<ul class="check"><li><b>LIE</b> (limite inférieure d’explosivité) : en dessous, le mélange est <b>trop pauvre</b> en gaz pour réagir.</li><li><b>LSE</b> (limite supérieure d’explosivité) : au-dessus, le mélange est <b>trop riche</b> en gaz.</li><li><b>Zone d’explosivité</b> : entre LIE et LSE.</li><li><b>Mélange idéal (stœchiométrie)</b> : point entre LIE et LSE où la combustion est la plus intense (le livret écrit par erreur « entre la LIE et la LIE »).</li></ul>' +
        '<div class="tw"><table><thead><tr><th>Zone</th><th>Mélange</th><th>Risque</th></tr></thead><tbody><tr><td>1</td><td>Trop pauvre</td><td>Pas de risque d’explosion ; zone contrôlée par l’explosimètre.</td></tr><tr><td>2</td><td>Domaine d’inflammabilité / explosion</td><td>Danger maximal.</td></tr><tr><td>3</td><td>Trop riche</td><td>Risque <b>non écarté</b> : en ventilant, le mélange retombe dans le domaine d’explosion.</td></tr></tbody></table></div>' +
        '<div class="tw"><table><thead><tr><th>Gaz</th><th>LIE</th><th>LSE</th></tr></thead><tbody><tr><td>Hydrogène</td><td>4,1 %</td><td>74,5 %</td></tr><tr><td>Oxyde de carbone</td><td>12,5 %</td><td>74,2 %</td></tr><tr><td>Méthane</td><td>5,3 %</td><td>15,4 %</td></tr><tr><td>Propane</td><td>2,2 %</td><td>9,5 %</td></tr><tr><td>Butane</td><td>1,9 %</td><td>8,4 %</td></tr><tr><td>Acétylène</td><td>1,5 %</td><td>&gt; 80 %</td></tr></tbody></table></div>' +
        '<p class="small">Les termes LII / LSI (limites d’inflammabilité) sont, d’un point de vue opérationnel, considérés comme identiques à LIE / LSE.</p>',
      figs: [{ img: 'img/inc/5/explosimetre-zones.jpg', cap: 'Zone de recherche de l’explosimètre', txt: '<p>L’explosimètre travaille dans la zone verte, de 0 à 100 % de la LIE. Au-delà commence la zone dangereuse (entre LIE et LSE). Le seuil d’alarme figuré est à 20 % de la LIE.</p>', src: 'Diaporama « Les fuites de gaz » (SDIS 51)' }] },
    { id: 'appareil', t: 'L’explosimètre et ses limites', ic: 'eye', src: L5 + ', § 2.6 § 3, p. 50 ; Guide d’instruction INC',
      html: '<p>L’explosimètre est un appareil portatif qui mesure un taux de concentration d’un gaz et déclenche des alarmes sonores et visuelles à des teneurs prédéterminées. Il est <b>étalonné</b> sur un <b>gaz étalon</b> (le plus souvent le <b>méthane</b>) et mesure <b>de 0 à 100 % de la LIE</b>.</p>' +
        '<p>Les appareils des techniciens gaziers sont des <b>catharomètres</b> : ils mesurent de 0 à 100 % <b>de gaz</b> (principe différent).</p>' +
        '<div class="callout warn"><b>Le mélange n’est jamais homogène.</b> Les poches se déplacent selon la densité du gaz et l’aéraulique (ventilation, gaines techniques, chauffage). On ne peut affirmer être sous la LIE qu’après avoir :<ul><li>localisé <b>et stoppé</b> la fuite ;</li><li>inspecté <b>tous les volumes, en partie haute et basse</b> ;</li><li>pris connaissance du gaz mesuré (appareils étalonnés au méthane).</li></ul>Si le gaz n’est pas le gaz étalon, le <b>COS</b> fait la conversion à l’aide d’un abaque.</div>' +
        '<p><b>Densité :</b> gaz de densité &gt; 1 (plus lourd que l’air) : chercher en <b>partie basse</b> ; densité &lt; 1 : en <b>partie haute</b>. Le guide conseille de laisser un explosimètre « balise » en zone d’exclusion pour contrôler en permanence la pertinence du périmètre.</p>' },
    { id: 'microclip', t: 'Le détecteur BW GasAlert MicroClip', ic: 'clip', src: 'Diaporama « Les fuites de gaz » (SDIS 51) : matériel de détection',
      html: '<p>Détecteur multifonction <b>2 gaz</b> (CO et LIE, capteur LIE étalonné au méthane), pris en compte par le <b>chef d’équipe</b> pour effectuer les détections. Poids : 160 g ; fonctionnement de −20 °C à +58 °C ; mesures instantanées.</p>' +
        '<div class="tw"><table><thead><tr><th></th><th>Plage</th><th>Alarme basse</th><th>Alarme haute</th></tr></thead><tbody><tr><td><b>CO</b></td><td>0 à 500 ppm</td><td>50 ppm</td><td>200 ppm</td></tr><tr><td><b>LIE</b></td><td>0 à 100 %</td><td>20 %</td><td>60 %</td></tr></tbody></table></div>' +
        '<ul class="check"><li><b>TWA</b> : valeur moyenne d’exposition (base 8 à 10 h par jour et/ou 40 à 42 h par semaine).</li><li><b>STEL</b> : valeur limite d’exposition de courte durée (période de 15 minutes).</li><li><b>OL</b> (over limit) : dépassement d’échelle, alarmes sonores et visuelles continues.</li><li>Arrêt automatique (batterie faible) : 8 bips, 8 flashs, « FAIBLE », puis « ETEINDR ».</li><li>Recharge 2 à 3 h, <b>détecteur éteint</b> ; nettoyage au chiffon doux légèrement humide, sans solvant, sans immersion.</li></ul>',
      figs: [{ img: 'img/inc/5/detecteur-microclip.jpg', cap: 'Description du détecteur MicroClip', txt: '<p>Barres d’alarme (LED), affichage, alarme sonore, touche fonctions, capteurs LIE et CO ; au dos, pince et connecteur de recharge.</p>', src: 'Diaporama « Les fuites de gaz » (SDIS 51)' }] },
    { id: 'co', t: 'Le monoxyde de carbone (CO)', ic: 'skull', src: 'Diaporama « Les fuites de gaz » (SDIS 51) : le monoxyde de carbone',
      html: '<p>Gaz issu d’une <b>mauvaise combustion</b> (chaudières, chauffe-eau, moteurs thermiques…) ou des fumées d’incendie ; <b>inodore, incolore, insipide</b>, de densité voisine de l’air (<b>0,96</b>). Il se fixe sur l’hémoglobine et empêche le transport de l’oxygène : intoxication rapide et insidieuse (vertiges, impotence musculaire, perte de connaissance, coma, décès).</p>' +
        '<div class="tw"><table><thead><tr><th>CO dans l’air</th><th>Effet</th></tr></thead><tbody><tr><td>≤ 50 ppm (seuil d’alerte bas)</td><td>Pas d’effets physiologiques</td></tr><tr><td>100 ppm</td><td>Céphalées</td></tr><tr><td>200 ppm</td><td>Nausées</td></tr><tr><td>500 ppm</td><td>Vomissements, perte de conscience brève</td></tr><tr><td>1 000 ppm</td><td>Coma par intoxication grave</td></tr><tr><td>2 000 ppm</td><td>Mortel en 4 à 5 heures</td></tr><tr><td>5 000 ppm</td><td>Mortel en 20 minutes</td></tr></tbody></table></div><p class="small">1 ppm = 0,0001 % de produit.</p>' }
  ],
  key: ['Explosimètre : 0 à 100 % de la LIE, gaz étalon le plus souvent méthane.', 'MicroClip : alarmes LIE 20 % / 60 % ; CO 50 / 200 ppm.', 'Méthane : LIE 5,3 % – LSE 15,4 %.', 'Au-dessus de la LSE, le danger n’est pas écarté : la ventilation ramène dans la zone explosive.', 'Sous la LIE seulement si fuite stoppée, tous volumes (haut et bas) contrôlés, gaz identifié.', 'Déflagration < vitesse du son (4-10 bars) ; détonation > vitesse du son (20-30 bars).', 'CO : inodore, incolore, insipide, densité 0,96.'],
  traps: ['Prendre une mesure à 0 % à un seul endroit pour une absence de danger.', 'Croire qu’un mélange trop riche est sans risque.', 'Oublier que l’appareil est étalonné au méthane : conversion par le COS pour un autre gaz.'],
  quiz: [
    { q: 'L’explosimètre mesure :', c: ['De 0 à 100 % de la LIE', 'De 0 à 100 % de gaz', 'De la LIE à la LSE', 'Uniquement le CO'], e: 'Livret p. 50 : il mesure entre 0 et 100 % de la LIE. Les catharomètres des gaziers mesurent de 0 à 100 % de gaz.', s: 'appareil' },
    { q: 'Seuils d’alarme LIE du détecteur MicroClip :', c: ['20 % (basse) et 60 % (haute)', '10 % et 50 %', '50 % et 100 %', '5 % et 15 %'], e: 'Diaporama gaz : LIE alarme basse 20 %, haute 60 %.', s: 'microclip' },
    { q: 'Domaine d’explosivité du méthane :', c: ['5,3 % à 15,4 %', '1,9 % à 8,4 %', '4,1 % à 74,5 %', '12,5 % à 74,2 %'], e: 'Tableau du livret p. 49.', s: 'limites' },
    { q: 'Le mélange est au-dessus de la LSE (trop riche). Que retenir ?', c: ['Le danger demeure : en ventilant, il repasse dans la zone explosive', 'Aucun risque, on peut ventiler sans précaution', 'Le gaz devient ininflammable définitivement', 'L’explosimètre affiche 0 %'], e: 'Livret, zone 3 : le risque d’explosion n’est pas pour autant écarté.', s: 'limites' },
    { q: 'Où rechercher un gaz de densité supérieure à 1 ?', c: ['En partie basse', 'En partie haute', 'Uniquement à l’extérieur', 'Au milieu de la pièce'], e: 'Plus lourd que l’air : partie basse (diaporama « propriété des gaz »).', s: 'appareil' },
    { q: 'Seuils d’alarme CO du MicroClip :', c: ['50 ppm et 200 ppm', '20 ppm et 60 ppm', '100 ppm et 500 ppm', '200 ppm et 1 000 ppm'], e: 'Diaporama gaz : CO plage 0-500 ppm, alarme basse 50 ppm, haute 200 ppm.', s: 'microclip' },
    { q: 'Une détonation se distingue d’une déflagration par :', c: ['Une vitesse supérieure à celle du son', 'Une vitesse inférieure à celle du son', 'L’absence de surpression', 'L’absence de flamme'], e: 'Livret p. 48 : détonation > vitesse du son (20 à 30 bars) ; déflagration < vitesse du son (4 à 10 bars).', s: 'definitions' },
    { q: 'L’explosimètre indique 0 % dans l’entrée. Peut-on conclure à l’absence de risque ?', c: ['Non : il faut fuite stoppée, tous volumes contrôlés en haut et en bas, gaz identifié', 'Oui, la mesure fait foi', 'Oui si l’alarme ne sonne pas', 'Oui après 5 minutes'], e: 'Livret p. 50 : le mélange n’est jamais homogène ; trois conditions sont nécessaires.', s: 'appareil' }
  ]
});

/* ================================================================ 4. Fuites de gaz */
VSAV.chap({
  id: 'inc-fuites-gaz', part: 'inc', seq: INC8,
  title: 'Les fuites de gaz : réseau, organes de coupure, procédures', short: 'Fuites de gaz', motif: 'alert',
  sources: ['Diaporama « Les fuites de gaz » (SDIS 51)', 'Guide d’instruction et de manœuvre INC — le risque explosif : procédures gaz, zonage, méthodologie'],
  summary: 'Ce que le sapeur-pompier peut fermer (et ce qu’il ne doit jamais toucher), PGC/PGR, périmètres et règles d’engagement.',
  why: '<b>Pourquoi tant d’interdits ?</b> Une explosion de gaz tue (le guide rappelle un accident à la BSPP : 2 SP et une touriste décédés). Une vanne de réseau mal manœuvrée peut priver de gaz tout un quartier et créer d’autres fuites à la remise en service : seul GRDF agit sur le réseau. Le sapeur-pompier, lui, isole un branchement, protège les personnes et limite le nuage.',
  sections: [
    { id: 'types', t: 'Types de fuites et réseau', ic: 'list', src: 'Diaporama « Les fuites de gaz » : les différentes fuites, le réseau',
      html: '<p>On distingue la <b>fuite enflammée</b>, la <b>fuite à l’air libre</b> (voie publique) et la <b>fuite en milieu clos</b> (bâtiment), de gaz de ville ou de gaz en bouteille (conditionnement).</p>' +
        '<div class="tw"><table><thead><tr><th>Réseau</th><th>Gestionnaire</th><th>Caractéristiques</th></tr></thead><tbody><tr><td><b>Transport</b></td><td>GRTgaz</td><td>Gazoducs de 80 à 1 000 mm ; le plus souvent 67 bars, jusqu’à 85 bars ; enterrés à environ 1 m, signalés par des balises.</td></tr><tr><td><b>Distribution</b></td><td>GrDF</td><td>Du poste de livraison GRTgaz jusqu’au particulier : 16 bars, puis 4 bars (conduite voie publique), puis <b>21 mbar</b> au compteur individuel.</td></tr></tbody></table></div>' },
    { id: 'coupure', t: 'Organes de coupure : autorisé ou interdit ?', ic: 'check', src: 'Diaporama « Les fuites de gaz » : les organes de coupure, les branchements, les postes gaz ; Guide d’instruction INC',
      html: '<div class="tw"><table><thead><tr><th>Organe</th><th>Repère</th><th>SP</th></tr></thead><tbody><tr><td>Vannes de <b>réseau</b></td><td>Plaques le plus souvent <b>rectangulaires</b>, sigle « réseau »</td><td><b>INTERDIT</b> (agents GrDF uniquement)</td></tr><tr><td>Postes de détente et de livraison « réseau » ou « DP » (distribution publique)</td><td>Inscription sur le poste</td><td><b>INTERDIT</b></td></tr><tr><td>Branchements gaz <b>sur rue</b></td><td>Plaques le plus souvent <b>rondes</b>, sigle « branchement »</td><td>Autorisé : fermeture <b>¼ de tour à droite</b>, <b>en dernier recours</b> ; en cas de doute, s’abstenir et attendre GrDF</td></tr><tr><td>Branchements <b>en élévation</b> (coffrets)</td><td>Alimentation toujours par la <b>gauche</b></td><td>Autorisé : « coup de poing » ou ¼ de tour à droite</td></tr><tr><td>Postes de détente et de livraison « <b>client</b> »</td><td>Inscription « client »</td><td>Autorisé</td></tr></tbody></table></div>' +
        '<p>En élévation : si la conduite arrive en 4 bars, un <b>détendeur</b> est présent avant le compteur ; sinon la pression est de 21 mbar. Le guide précise que les SP ne peuvent intervenir sur le réseau de distribution <b>quelle que soit la pression</b>, mais peuvent fermer les robinets de branchement et de <b>pied de conduite montante</b> d’immeuble.</p>' +
        '<div class="callout warn"><b>Quel que soit l’organe manœuvré :</b> il ne doit <b>jamais être rouvert</b> ; une <b>plaque de coupure</b> est posée ; l’agent GrDF est <b>informé</b> à son arrivée.</div>',
      figs: [
        { img: 'img/inc/5/plaque-reseau.jpg', cap: 'Plaque « gaz réseau » : manœuvre interdite', txt: '<p>Plaque rectangulaire signalant une vanne de réseau : seuls les agents GrDF la manœuvrent.</p>', src: 'Diaporama « Les fuites de gaz » (SDIS 51)' },
        { img: 'img/inc/5/plaque-branchement.jpg', cap: 'Plaque « gaz branchement » : manœuvre autorisée', txt: '<p>Plaque ronde « branchement » : fermeture ¼ de tour à droite, en dernier recours.</p>', src: 'Diaporama « Les fuites de gaz » (SDIS 51)' },
        { img: 'img/inc/5/plaque-coupure-pompiers.jpg', cap: 'Plaque de coupure', txt: '<p>« Robinet gaz fermé par les pompiers — ne peut être réouvert que par un agent du GDF » : à poser après toute fermeture.</p>', src: 'Diaporama « Les fuites de gaz » (SDIS 51)' }
      ] },
    { id: 'procedures', t: 'Procédures gaz classique et renforcée', ic: 'team', src: 'Diaporama « Les fuites de gaz » (SDIS 51) ; Guide d’instruction INC — procédures gaz',
      html: '<div class="tw"><table><thead><tr><th></th><th>Sapeurs-pompiers (diaporama SDIS 51)</th><th>GRDF</th></tr></thead><tbody><tr><td><b>PGC</b> (procédure gaz classique)</td><td>1 FPT + chef de groupe</td><td>1 opérateur gaz</td></tr><tr><td><b>PGR</b> (procédure gaz renforcée)</td><td>2 FPT + VSAV + chef de groupe + chef de colonne et son PC + information RCH 3</td><td>2 opérateurs gaz + ATCE</td></tr></tbody></table></div>' +
        '<p>Le choix dépend de la localisation (voie publique ou bâtiment) et des facteurs aggravants : bruit, sifflement, nuage gazeux, fuite enflammée, population impactée, ERP, météorologie…</p>' +
        '<p>Le guide d’instruction précise que la PGC représente la majorité des interventions et peut être <b>requalifiée en PGR</b> par le chef d’agrès après reconnaissance, en accord avec l’opérateur GRDF ; la PGR vise à <b>lancer la coupure du réseau dès la réception de l’alerte</b>.</p>' +
        '<div class="callout warn"><b>Divergence de sources :</b> les engagements cités par le guide d’instruction (PGC : 1 FPT, 1 chef de groupe, GRDF ; PGR : 2 FPT, 1 chef de groupe, GRDF, forces de l’ordre) sont ceux du <b>SDIS de l’Oise</b> ; le diaporama donne la composition SDIS 51 reprise dans le tableau.</div>' },
    { id: 'perimetre', t: 'Zonage et règles d’engagement', ic: 'target', src: 'Diaporama « Les fuites de gaz » : périmètre de sécurité, règles à respecter ; Guide d’instruction INC — zonage, méthodologie',
      html: '<div class="tw"><table><thead><tr><th>Zone</th><th>Rayon (a priori)</th><th>Contenu</th></tr></thead><tbody><tr><td><b>Exclusion</b></td><td>50 m</td><td>SP directement exposés ; accès réservé aux personnels en EPI ; <b>évacuation complète par défaut</b> (le COS peut choisir le confinement si le passage près de la fuite est dangereux).</td></tr><tr><td><b>Contrôlée et de soutien</b></td><td>100 m</td><td>Zone tampon où est coordonné l’engagement ; interdite au public.</td></tr></tbody></table></div>' +
        '<p>Effets d’une explosion justifiant l’évacuation (guide) : effondrement, brûlures graves, éclatement des alvéoles pulmonaires, perforation des tympans, projections, effet de souffle.</p>' +
        '<ul class="check"><li>Retirer tous les <b>appareils électriques</b> (bip, portables…).</li><li><b>EPI complets</b> : veste, surpantalon, gants, cagoule, casque et <b>ARI</b>.</li><li>Le <b>chef d’équipe prend l’explosimètre</b>.</li><li><b>Minimum de personnel</b> engagé.</li><li><b>Allumer les lampes avant</b> d’entrer en zone d’exclusion.</li><li>Tenir compte du <b>bruit</b> (comparable à un réacteur d’avion sur haute/moyenne pression) : protections auditives.</li><li>Établir une lance <b>« queue de paon »</b> et/ou une LDV pour limiter la diffusion du nuage.</li></ul>' +
        '<div class="callout bad">Si la fuite est dans une fouille : <b>ne pas la remplir</b>. Sur une fuite de gaz enflammée : <b>ne pas éteindre la flamme</b>.</div>',
      steps: ['Prendre contact avec le requérant.', 'Valider la procédure à mettre en place (PGC ou PGR).', 'Établir le périmètre de sécurité (zones d’exclusion et contrôlée) avec procédure d’évacuation.', 'Porter les EPI en zone d’exclusion.', 'Réaliser les mesures d’explosimétrie (explosimètre « balise » conseillé en zone d’exclusion).', 'Anticiper l’évolution possible (explosion, incendie, sur-accident).', 'Maîtrise de la fuite par l’opérateur GRDF.', 'Fin des opérations après de nouveaux relevés d’explosimétrie.'], stepsTitle: 'Méthodologie opérationnelle (guide d’instruction)' }
  ],
  key: ['Vannes et postes « réseau » / « DP » : manœuvre INTERDITE.', 'Branchement (plaque ronde) : ¼ de tour à droite, en dernier recours.', 'Organe fermé : jamais rouvert, plaque posée, GrDF informé.', 'Zone d’exclusion 50 m, zone contrôlée 100 m (a priori).', 'Lampes allumées avant d’entrer ; appareils électriques retirés.', 'Fuite enflammée : ne pas éteindre la flamme ; fouille : ne pas la remplir.', 'Pression au compteur individuel : 21 mbar.'],
  traps: ['Éteindre une fuite de gaz enflammée : le gaz continue de fuir et forme un nuage explosif.', 'Allumer sa lampe une fois dans la zone d’exclusion.', 'Manœuvrer une vanne « réseau » parce qu’elle est accessible.', 'Positionner l’engin devant l’adresse (le guide : 50 m en amont).'],
  quiz: [
    { q: 'Une plaque rectangulaire porte le sigle « réseau ». Vous :', c: ['Ne la manœuvrez pas : réservé aux agents GrDF', 'Fermez d’un ¼ de tour à droite', 'Fermez en « coup de poing »', 'Fermez seulement si l’explosimètre sonne'], e: 'Diaporama : toutes les vannes « réseau » ne doivent pas être manœuvrées par les SP.', s: 'coupure' },
    { q: 'Comment se ferme une vanne de branchement gaz sur rue ?', c: ['¼ de tour à droite', '¼ de tour à gauche', 'Un tour complet', 'Par tirage'], e: 'Diaporama : fermeture en ¼ de tour à droite, en dernier recours.', s: 'coupure' },
    { q: 'Rayon a priori de la zone d’exclusion sur fuite de gaz :', c: ['50 m', '10 m', '100 m', '300 m'], e: 'Diaporama et guide : exclusion 50 m, contrôlée 100 m.', s: 'perimetre' },
    { q: 'Fuite de gaz enflammée sur la voie publique :', c: ['Ne pas éteindre la flamme ; limiter la propagation (queue de paon / LDV)', 'Éteindre immédiatement à la poudre', 'Remplir la fouille d’eau', 'Étouffer avec de la terre'], e: 'Diaporama : ne pas éteindre la flamme sur une fuite de gaz enflammée, ne pas remplir la fouille.', s: 'perimetre' },
    { q: 'Quand allumer les lampes ?', c: ['Avant de pénétrer dans la zone d’exclusion', 'Une fois dans le local', 'Jamais', 'Après la mesure d’explosimétrie'], e: 'Allumer en zone, c’est créer une source d’ignition potentielle là où le gaz est présent.', s: 'perimetre' },
    { q: 'Après avoir fermé un robinet de branchement :', c: ['Ne jamais le rouvrir, poser une plaque de coupure, informer GrDF', 'Le rouvrir après aération', 'Le rouvrir à la demande du propriétaire', 'Retirer la poignée'], e: 'Diaporama : quel que soit l’organe manœuvré, il n’est jamais rouvert, une plaque est posée et l’agent GrDF est informé.', s: 'coupure' },
    { q: 'Selon le diaporama SDIS 51, la PGR engage côté SP :', c: ['2 FPT + VSAV + chef de groupe + chef de colonne et son PC + information RCH 3', '1 FPT + chef de groupe', '1 VSAV seul', '2 FPT seulement'], e: 'La PGC engage 1 FPT + chef de groupe. Le guide cite une autre composition, celle du SDIS de l’Oise.', s: 'procedures' }
  ]
});

/* ================================================================ 5. Chimique et radiologique */
VSAV.chap({
  id: 'inc-rch-rad', part: 'inc', seq: INC8,
  title: 'Risques chimique et radiologique', short: 'Chimique et radiologique', motif: 'molecule',
  sources: [L5 + ', § 7.3 Le risque chimique, p. 115-120', L5 + ', § 7.4 Le risque radiologique, p. 121-124'],
  summary: 'Identifier le danger (plaque orange, étiquettes), se placer dos au vent, zoner, et se protéger par le temps, la distance et les écrans.',
  why: '<b>Pourquoi le premier engin reste-t-il en retrait ?</b> Le produit est souvent inconnu à l’arrivée, invisible ou inodore. Le rôle du premier intervenant est de <b>caractériser le risque</b> et de <b>limiter l’exposition</b>, pas de traiter la fuite : la CMIC/CMIR apporte ensuite équipements et procédures spécialisés.',
  sections: [
    { id: 'chimique', t: 'Le risque chimique : généralités', ic: 'molecule', src: L5 + ', § 7.3.1, p. 115 et 118',
      html: '<ul class="check"><li><b>Origines</b> : sites industriels de production, transport de matières dangereuses, terrorisme.</li><li><b>Formes</b> : dispersion dans l’air, l’eau ou le sol ; incendie par inflammation d’un produit ; explosion par mélange de produits.</li><li><b>Effets</b> : inflammabilité et explosivité ; toxicité aiguë ou chronique des intervenants et de la population ; pollution.</li></ul>' +
        '<p><b>Scénarios dimensionnants</b> : <b>BLEVE</b> (rupture d’un réservoir de gaz combustible liquéfié, vaporisation et boule de feu), <b>UVCE</b> (explosion d’un nuage de gaz combustible après une fuite), brèche sur un véhicule de gaz toxique liquéfié, fuite de gaz toxique sur réservoir ou canalisation, incendie de bacs de liquides inflammables, explosion d’un dépôt d’explosifs, incendie d’entrepôt phytosanitaire ou décomposition d’engrais.</p>' },
    { id: 'identification', t: 'Identifier : plaque orange et code danger', ic: 'eye', src: L5 + ', § 7.3.1 § 1, p. 115-117',
      html: '<p>La plaque orange porte en haut le <b>code danger</b>, en bas le <b>code matière (n° ONU)</b>.</p>' +
        '<div class="tw"><table><thead><tr><th>Chiffre</th><th>Danger</th></tr></thead><tbody><tr><td>0</td><td>Absence de danger secondaire</td></tr><tr><td>1</td><td>Matières explosives</td></tr><tr><td>2</td><td>Émanation de gaz (pression ou réaction chimique)</td></tr><tr><td>3</td><td>Inflammabilité de liquide et gaz, ou liquide auto-échauffant</td></tr><tr><td>4</td><td>Inflammabilité de solide ou solide auto-échauffant</td></tr><tr><td>5</td><td>Comburant (favorise l’incendie)</td></tr><tr><td>6</td><td>Toxicité ou danger d’infection</td></tr><tr><td>7</td><td>Radioactivité</td></tr><tr><td>8</td><td>Corrosivité</td></tr><tr><td>9</td><td>Danger de réaction violente spontanée</td></tr></tbody></table></div>' +
        '<ul class="check"><li>Le <b>redoublement</b> d’un chiffre indique une <b>intensification</b> du danger (ex. 33 : liquide très inflammable), sauf 22 (gaz liquéfié réfrigéré, asphyxiant), 44 (solide inflammable fondu à haute température), 99 (matières dangereuses diverses transportées à chaud).</li><li>Un seul chiffre suffisant est suivi de <b>0</b> (ex. 40 : solide inflammable).</li><li>Un <b>X</b> devant le code : <b>réaction dangereuse avec l’eau</b> (ex. X88 : matière très corrosive réagissant dangereusement avec l’eau).</li><li>Autres exemples : 23 gaz inflammable ; 58 comburant et corrosif ; 268 gaz toxique et corrosif ; 333 liquide pyrophorique ; 606 matière infectieuse.</li></ul>' +
        '<p>Les étiquettes de danger (classes 1 à 9, losanges) complètent l’identification ; dans tous les cas, les responsables d’entreprises ou les transporteurs sont les personnes les plus susceptibles de fournir des informations immédiatement exploitables.</p>' +
        '<p class="small muted">Note : dans le tableau des étiquettes du livret (p. 116), les libellés des classes 8 et 9 reprennent par erreur ceux des classes 6 et 7 ; le code danger ci-dessus attribue le chiffre 8 à la corrosivité.</p>',
      figs: [{ img: 'img/inc/5/plaque-orange.jpg', cap: 'La plaque orange', txt: '<p>En haut, le code danger (ici 33 : liquide très inflammable) ; en bas, le n° ONU de la matière (ici 1203).</p>', src: L5 + ', p. 116' }] },
    { id: 'conduite', t: 'Conduite à tenir et zonage', ic: 'target', src: L5 + ', § 7.3 § 3, p. 119-120',
      html: '<p>L’engagement des binômes se <b>cantonne d’abord aux sauvetages et aux reconnaissances strictement nécessaires</b> (présence ou non de victimes). Le premier intervenant détermine : fuite ou rupture d’étanchéité, importance du phénomène, nombre de personnes impliquées, topographie, conditions climatiques (température, humidité, <b>vent</b>).</p>' +
        '<div class="callout warn">Premières règles : <b>rester dans la zone opposée au sens du vent</b> et <b>éviter tout contact avec le produit</b>.</div>' +
        '<p>Ensuite, avec la <b>CMIC</b> : EPI adaptés, procédures d’habillage / déshabillage, règles d’engagement strictes (respect des consignes, contact permanent dans le binôme ; <b>pour tout binôme engagé, un binôme de sécurité prêt à intervenir</b>), zonage tenant compte du vent et de la population :</p>' +
        '<div class="tw"><table><tbody><tr><td><b>Zone d’exclusion</b></td><td>« zone rouge »</td></tr><tr><td><b>Zone contrôlée</b></td><td>« zone orange »</td></tr><tr><td><b>Zone de soutien</b></td><td>« zone verte »</td></tr></tbody></table></div>' +
        '<p><b>Grandes actions</b> : <b>regrouper</b> les personnes impliquées (prise en charge médicale à l’écart, en zone verte) ; <b>limiter l’évolution</b> (barrage de terre ou de sable, fermeture de vanne, colmatage, bacs de rétention… selon le produit, la température, la brèche, le contenant) ; <b>transmettre des comptes rendus</b> (lieu, environnement, nature du risque, blessés, évolution possible, mesures prises, produit, aspect, toxicité, dangers associés).</p>',
      figs: [{ img: 'img/inc/5/zonage-rch.jpg', cap: 'Le zonage en risque chimique', txt: '<p>Zone rouge autour du point d’émission, zone orange où se coordonne l’engagement, zone verte où sont regroupés victimes et moyens, en tenant compte du sens du vent.</p>', src: L5 + ', p. 120' }] },
    { id: 'radio', t: 'Le risque radiologique', ic: 'alert', src: L5 + ', § 7.4.1 à 7.4.2, p. 121-123',
      html: '<p>Certains atomes ont un noyau <b>instable</b> qui évolue spontanément vers la stabilité en émettant des rayonnements ou des particules : c’est la <b>désintégration</b>. Certains rayonnements ont un parcours très court (quelques cm dans l’air, arrêtés par une feuille de papier ou l’épiderme), d’autres ne sont que partiellement arrêtés par le plomb ou le béton.</p>' +
        '<p>Les lésions dépendent de la <b>dose</b> (énergie cédée). Effets rapides à partir d’une certaine dose : troubles sanguins, lésions de la peau et brûlures, perte de cheveux, troubles digestifs, grande fatigue et infections, troubles nerveux, mort. D’autres (cancer, leucémie) apparaissent à moyen ou long terme.</p>' +
        '<div class="tw"><table><thead><tr><th></th><th>Irradiation</th><th>Contamination</th></tr></thead><tbody><tr><td>Source</td><td>À distance, pas au contact de la peau</td><td>Au contact de l’organisme : <b>externe</b> (sur la peau) ou <b>interne</b> (voies aériennes, digestives, blessures)</td></tr><tr><td>Comment s’y soustraire</td><td>S’éloigner</td><td>Se faire <b>décontaminer</b></td></tr><tr><td>Transmissible ?</td><td>Non</td><td><b>Oui</b> (toucher une surface contaminée)</td></tr></tbody></table></div>' },
    { id: 'protection', t: 'Se protéger : temps, écrans, distance', ic: 'shield', src: L5 + ', § 7.4.3 et 7.4.4, p. 123-124',
      html: '<ul class="check"><li><b>Temps</b> : plus l’exposition est longue, plus la dose est importante : rester exposé le moins longtemps possible.</li><li><b>Écrans</b> : les plus massifs possibles, ils atténuent en partie les rayonnements.</li><li><b>Distance</b> : plus on est loin de la source, moins on est atteint.</li></ul>' +
        '<p><b>Contre la contamination</b> : les spécialistes de la CMIR portent une tenue adaptée (la tenue de feu est aussi une bonne protection de la peau) ; contre la contamination interne, porter l’<b>ARI</b> ou un AR filtrant.</p>' +
        '<p>La radioactivité naturelle est partout (sol granitique, matériaux de construction, eau, rayons cosmiques) ; certains objets usuels en émettent (carreaux en céramique, bijoux émaillés, manchons de camping-gaz). Le SDIS 51 dispose de <b>2 VRT</b> (véhicules risques technologiques, répartis CSPR CHAL et RMAR) pour transporter et déployer une équipe RCH ou RAD.</p>' }
  ],
  key: ['Rester dos au vent, éviter tout contact avec le produit.', 'Engagement limité aux sauvetages et reconnaissances strictement nécessaires.', 'Zones : exclusion (rouge), contrôlée (orange), soutien (verte).', 'Plaque orange : code danger en haut, n° ONU en bas ; X = réagit dangereusement avec l’eau.', 'Redoublement d’un chiffre = danger intensifié.', 'Radioprotection : temps, écrans, distance.', 'Contamination transmissible ; irradiation non.'],
  traps: ['Arroser une matière marquée X.', 'Confondre irradiation (s’éloigner) et contamination (décontaminer).', 'Regrouper les victimes sous le vent du produit.'],
  quiz: [
    { q: 'Que signifie la lettre X devant le code danger ?', c: ['Réaction dangereuse avec l’eau', 'Matière explosive', 'Danger inconnu', 'Matière radioactive'], e: 'Livret p. 117 : code danger précédé d’un X = réaction dangereuse avec l’eau.', s: 'identification' },
    { q: 'Le code danger 33 signifie :', c: ['Liquide très inflammable', 'Gaz inflammable', 'Matière comburante', 'Matière toxique'], e: 'Le redoublement indique une intensification : 3 = inflammable, 33 = très inflammable.', s: 'identification' },
    { q: 'Premières règles de sécurité en risque chimique :', c: ['Rester dans la zone opposée au sens du vent et éviter tout contact avec le produit', 'S’approcher pour lire l’étiquette au plus près', 'Diluer immédiatement à la lance', 'Ventiler la zone'], e: 'Livret p. 119.', s: 'conduite' },
    { q: 'La zone contrôlée est aussi appelée :', c: ['Zone orange', 'Zone rouge', 'Zone verte', 'Zone noire'], e: 'Exclusion = rouge, contrôlée = orange, soutien = verte.', s: 'conduite' },
    { q: 'Les trois moyens de protection contre l’irradiation :', c: ['Temps, écrans, distance', 'Eau, mousse, poudre', 'ARI, gants, bottes', 'Vent, pluie, froid'], e: 'Livret § 7.4.3.', s: 'protection' },
    { q: 'Une personne a touché une surface contaminée. Que retenir ?', c: ['Elle peut être contaminée : la contamination est transmissible', 'Aucun risque, seule l’irradiation compte', 'Il suffit qu’elle s’éloigne', 'Elle est irradiée mais pas contaminée'], e: 'Livret p. 123 : la contamination est transmissible ; on s’en soustrait par la décontamination.', s: 'radio' },
    { q: 'Que représente le BLEVE ?', c: ['La rupture d’un réservoir de gaz liquéfié avec boule de feu', 'L’explosion d’un nuage de gaz à l’air libre', 'Une fuite de gaz toxique', 'Un feu de bac'], e: 'L’UVCE est l’explosion d’un nuage de gaz combustible suite à une fuite.', s: 'chimique' }
  ]
});

/* ================================================================ 6. Inondation et pollution */
VSAV.chap({
  id: 'inc-inondation-pollution', part: 'inc', seq: INC8,
  title: 'Risques inondation et pollution', short: 'Inondation et pollution', motif: 'wave',
  sources: [L5 + ', § 7.2 Le risque inondation, p. 112-114', L5 + ', § 7.5 Le risque pollution, p. 125-126'],
  summary: 'Les types d’inondation, les règles de sécurité près de l’eau, les polluants et les mesures opérationnelles (dilution, dispersion, barrage).',
  why: '<b>Pourquoi des règles « obligatoires » près de l’eau ?</b> Le livret le dit sans détour : la sanction peut être <b>fatale</b>. Courant, plaques d’égout soulevées, tranchées invisibles et bottes qui se remplissent piègent même un sauveteur entraîné. En pollution, l’enjeu est de <b>contenir</b> le produit avant qu’il n’atteigne l’eau potable ou les réseaux.',
  sections: [
    { id: 'inondation', t: 'L’inondation', ic: 'wave', src: L5 + ', § 7.2.1, p. 112-113',
      html: '<p>Submersion plus ou moins rapide d’une zone, due à l’augmentation du débit d’un cours d’eau après des pluies importantes et durables ; prévisible ou non selon la vitesse de montée des eaux.</p>' +
        '<p><b>Modes</b> : stagnation des eaux pluviales, submersion des zones littorales ou lacustres, destruction d’ouvrages (digues, barrages), ruissellement trop rapide, coulées de boue.</p>' +
        '<div class="tw"><table><thead><tr><th>Type</th><th>Mécanisme</th></tr></thead><tbody><tr><td>Débordement direct</td><td>Le cours d’eau sort de son lit mineur pour occuper son lit majeur.</td></tr><tr><td>Débordement indirect</td><td>Les eaux remontent par les nappes alluviales (phréatiques), les réseaux d’assainissement…</td></tr><tr><td>Ruissellement</td><td>Trop rapide sur les bassins.</td></tr></tbody></table></div>' +
        '<p>Aux facteurs naturels s’ajoutent des facteurs humains (déforestation, déviation de cours d’eau, urbanisation dans les lits majeurs).</p>',
      figs: [{ img: 'img/inc/5/inondation-nappes.jpg', cap: 'Mécanismes d’inondation', txt: '<p>Situation normale puis crue de la nappe, ruissellement, sources, rivière alimentée par la nappe, glissement de terrain, inondation de caves.</p>', src: L5 + ', p. 113 (illustration BRGM)' }] },
    { id: 'securite', t: 'Inondation : sécurité du sapeur-pompier', ic: 'shield', src: L5 + ', § 7.2.2 et 7.2.3, p. 114',
      html: '<p><b>Réflexe systématique</b> : s’équiper d’un <b>gilet pneumatique ou de sauvetage</b> ; tenue allégée vivement conseillée ; bottes ou cuissardes <b>une pointure au-dessus</b> (extraction rapide) ; <b>genouillères à proscrire</b> (risque de remplissage).</p>' +
        '<ul class="check"><li>Matériel d’autoprotection et <b>jamais seul</b>, à pied ou en embarcation.</li><li>À pied avec du courant : <b>assurance</b> par cordage ou lot de sauvetage.</li><li>Reconnaissance nécessitant le passage d’une zone en surface non libre : faire appel aux <b>plongeurs</b> ; progression à pied en courant élevé : plongeurs équipés <b>obligatoires</b>.</li><li>Mission héliportée : s’assurer de la charpente ; un plongeur équipé de palmes est préférable.</li><li>Dangers invisibles : <b>plaques d’égout retirées</b>, <b>tranchées</b> de travaux (se renseigner auprès des riverains).</li></ul>' },
    { id: 'pollution', t: 'La pollution', ic: 'drop', src: L5 + ', § 7.5.1, p. 125',
      html: '<ul class="check"><li><b>Polluants chimiques</b> : déchets industriels, hydrocarbures, détergents, engrais, phosphates… actifs sur la faune et la flore à faibles doses (&lt; 1 mg/l).</li><li><b>Polluants organiques</b> : rejets d’égouts, abattoirs, porcheries, laiteries, tanneries, papeteries, équarrissage…</li></ul>' +
        '<p>Milieux : eaux intérieures et maritimes (réseaux naturels : rus, rivières, plans d’eau, eaux souterraines ; réseaux artificiels : <b>eau potable</b>, <b>assainissement</b>), pollution solide (décharge), pollution atmosphérique (continue ou accidentelle). La pollution des cours d’eau et des nappes peut arrêter la distribution d’eau domestique, d’élevage ou industrielle.</p>' },
    { id: 'mesures', t: 'Pollution : mesures opérationnelles', ic: 'list', src: L5 + ', § 7.5 § 5, p. 126',
      html: '<div class="tw"><table><thead><tr><th>Mesure</th><th>Principe</th></tr></thead><tbody><tr><td><b>Dilution</b></td><td>Diminuer la teneur par adjonction d’eau ou d’un autre liquide.</td></tr><tr><td><b>Dispersion</b></td><td>Éparpiller, diviser finement le polluant dans la masse d’un autre élément.</td></tr><tr><td><b>Barrage</b></td><td>Levée de terre au sol, barrage flottant sur un cours d’eau, ou <b>tuyau de 70 en eau</b> pour les flux liquides ; si la pollution se dirige vers les égouts, les <b>obstruer</b>.</td></tr></tbody></table></div>' +
        '<p>Toute reconnaissance se fait dans la <b>tenue de protection adaptée</b>, surtout en présence de toxiques. Contraintes de l’habillage : durée d’intervention limitée, stress opérationnel important.</p>' +
        '<p><b>Principes de sécurité</b> : équipements en bon état, matériels spécifiques, conditions d’approche, facteurs de sur-accident. <b>Mesures conservatoires</b> : alerte des populations, mise en sécurité, confinement ou évacuation, périmètre de sécurité, limiter l’évolution, prélèvements.</p>' }
  ],
  key: ['Inondation : gilet de sauvetage, jamais seul.', 'Bottes une pointure au-dessus ; genouillères proscrites.', 'Courant : assurance par cordage ; courant élevé : plongeurs obligatoires.', 'Dangers cachés : plaques d’égout retirées, tranchées.', 'Pollution : dilution, dispersion, barrage (terre, flottant, tuyau de 70 en eau).', 'Pollution vers les égouts : les obstruer.'],
  traps: ['Traverser seul une zone inondée « peu profonde ».', 'Porter des genouillères dans l’eau.', 'Oublier que les réseaux d’eau potable et d’assainissement peuvent être atteints.'],
  quiz: [
    { q: 'Pourquoi chausser des bottes une pointure au-dessus en inondation ?', c: ['Pour pouvoir s’en extraire rapidement', 'Pour mettre deux paires de chaussettes', 'Pour mieux flotter', 'Par obligation réglementaire de taille'], e: 'Livret p. 114 : prévoir une pointure au-dessus en cas d’extraction rapide.', s: 'securite' },
    { q: 'Les genouillères en zone inondée sont :', c: ['À proscrire (risque de remplissage)', 'Obligatoires', 'Conseillées', 'Indifférentes'], e: 'Livret p. 114.', s: 'securite' },
    { q: 'Progression à pied dans une zone de courant élevé :', c: ['Emploi de plongeurs équipés obligatoire', 'Possible seul avec un gilet', 'Possible en binôme sans assurance', 'Interdite à tous'], e: 'Livret p. 114 : plongeurs équipés obligatoires.', s: 'securite' },
    { q: 'Le débordement indirect correspond à :', c: ['Une remontée des eaux par les nappes ou les réseaux d’assainissement', 'Un cours d’eau sortant de son lit mineur', 'Un ruissellement rapide', 'Une rupture de digue'], e: 'Livret p. 112.', s: 'inondation' },
    { q: 'Quel matériel courant le livret cite-t-il pour faire barrage à un flux polluant liquide ?', c: ['Un tuyau de 70 en eau', 'Une LDV 45 en jet diffusé', 'Une échelle à coulisse', 'Une bâche de ventilation'], e: 'Livret p. 126 : barrage au moyen d’un tuyau de 70 en eau.', s: 'mesures' },
    { q: 'La pollution se dirige vers des égouts :', c: ['Les obstruer', 'Diluer abondamment pour la faire passer', 'Laisser s’écouler', 'Ouvrir les regards'], e: 'Livret p. 126.', s: 'mesures' }
  ]
});

/* ================================================================ 7. Ascenseurs */
VSAV.chap({
  id: 'inc-ascenseurs', part: 'inc', seq: INC8,
  title: 'Les ascenseurs : personnes bloquées en cabine', short: 'Ascenseurs', motif: 'grid',
  sources: ['Diaporama « Les ascenseurs » (SDIS 51)', L5 + ', § 2.7, p. 54 (ascenseur prioritaire)'],
  summary: 'Comprendre les deux types d’ascenseurs puis dégager en sécurité des personnes bloquées en cabine.',
  why: '<b>Pourquoi couper le courant avant tout ?</b> Une cabine qui redémarre pendant qu’on manipule le frein ou qu’une personne sort, c’est l’écrasement. La coupure de la force (en gardant la lumière), la liaison radio entre la machinerie et le palier et la vérification de chaque porte palière font de cette intervention « banale » une opération sûre.',
  sections: [
    { id: 'principes', t: 'Définitions et types d’appareils', ic: 'book', src: 'Diaporama « Les ascenseurs » : définitions, différents principes',
      html: '<ul class="check"><li><b>Ascenseur</b> : transporte verticalement des personnes. <b>Monte-charge</b> : réservé aux charges, transport de personnes exclu. <b>Nacelle</b> : plate-forme de travail en hauteur, non utilisable par le public.</li><li>La <b>cabine</b> se déplace dans une <b>gaine</b>, supportée et guidée par l’<b>étrier</b>.</li></ul>' +
        '<div class="tw"><table><thead><tr><th></th><th>Traction électrique (à câbles)</th><th>Hydraulique</th></tr></thead><tbody><tr><td>Mouvement</td><td>Moteur électrique → poulie → câbles qui soutiennent la cabine</td><td>Piston d’un vérin alimenté en huile sous pression par une pompe (elle-même mue par un moteur électrique)</td></tr><tr><td>Contrepoids</td><td>Oui (équilibre la charge, augmente l’adhérence) ; absent sur les petits treuils à tambour</td><td>Aucun ; appareils plus lents</td></tr><tr><td>Course</td><td>Jusqu’aux IGH (poulie d’adhérence à moteur sophistiqué)</td><td>Déplacements courts, de l’ordre de <b>18 m</b> maximum</td></tr></tbody></table></div>' +
        '<p>Éléments de sécurité cités : treuil (moto-réducteur, poulie, frein, repères), parachute en bas de cabine, limiteur de vitesse. Les appareils récents <b>sans local de machinerie</b> nécessitent un personnel très qualifié en cas d’incident.</p>',
      figs: [{ img: 'img/inc/5/ascenseurs-types.jpg', cap: 'Ascenseur à traction et ascenseur hydraulique', txt: '<p>À gauche : treuil, câble et contrepoids. À droite : pistons télescopiques, cylindres, contrôleur et réservoir d’huile, butoir.</p>', src: 'Diaporama « Les ascenseurs » (SDIS 51)' }] },
    { id: 'mode', t: 'Personnes bloquées : mode opératoire', ic: 'team', src: 'Diaporama « Les ascenseurs » : personne(s) bloquée(s) dans une cabine',
      html: '<p>Trois temps préalables : <b>reconnaître les lieux</b> (type d’ascenseur, position de la cabine et de la machinerie), <b>couper le courant</b>, <b>prendre contact</b> avec la ou les personnes dans la cabine.</p>',
      steps: ['Une partie de l’équipage du FPT se rend à la machinerie avec une liaison radio et la pochette à clés.', 'L’autre partie reste près des personnes bloquées, avec un autre portatif.', 'Le personnel du dernier palier récupère l’échelle pour accéder à la machinerie.', 'Couper l’alimentation de la machinerie : la force uniquement, en laissant la lumière.', 'Prendre connaissance des consignes de sécurité et de manœuvre affichées dans le local machinerie.', 'Débloquer (débrayer) le système de freinage ; l’équipier manœuvre le volant en montée ou en descente.', 'Cabine au niveau du palier : prévenir le binôme de la machinerie pour sécuriser (relâcher le débrayage).', 'Le chef d’agrès décide de faire sortir les victimes.', 'Cabine vide : vérifier la fermeture de la porte palière.', 'La machinerie est refermée, l’appareil laissé hors service ; en redescendant, vérifier la fermeture des portes palières à chaque étage.'], stepsTitle: 'Dégagement de personnes bloquées',
      after: '<div class="callout ok">Le <b>chef d’agrès</b> s’assure de la fermeture effective de <b>toutes les portes palières</b> de tous les étages et demande au CTA-CODIS un <b>responsable de la société d’ascenseur</b>.</div>',
      figs: [{ img: 'img/inc/5/ascenseur-volant.jpg', cap: 'Manœuvre en machinerie', txt: '<p>Débrayage du frein et manœuvre au volant pour amener la cabine au niveau du palier, en liaison radio avec l’équipe restée près des victimes.</p>', src: 'Diaporama « Les ascenseurs » (SDIS 51)' }] },
    { id: 'prioritaire', t: 'L’ascenseur prioritaire pompiers', ic: 'star', src: L5 + ', § 2.7, p. 54',
      html: '<p>Certains ERP doivent avoir un ou plusieurs ascenseurs équipés du <b>dispositif d’appel prioritaire</b> pour les sapeurs-pompiers. Cette commande <b>prime sur toute autre</b>, sauf celles intéressant la maintenance, la sécurité des ascenseurs et le dégagement des usagers. Elle s’active par le <b>carré de la polycoise</b> ou par une <b>clé détenue par l’exploitant</b>.</p>' }
  ],
  key: ['Reconnaître, couper le courant, rassurer les personnes.', 'Couper la force uniquement, laisser la lumière.', 'Deux équipes reliées par radio : machinerie et palier.', 'Lire les consignes affichées dans la machinerie.', 'Appareil laissé hors service ; toutes les portes palières vérifiées.', 'Hydraulique : pas de contrepoids, course d’environ 18 m maximum.'],
  traps: ['Couper aussi l’éclairage de la cabine : les personnes paniquent.', 'Remettre l’ascenseur en service après le dégagement.', 'Oublier de vérifier les portes palières des autres étages.'],
  quiz: [
    { q: 'En machinerie, que coupe-t-on ?', c: ['La force uniquement, en laissant la lumière', 'Tout, y compris l’éclairage', 'Rien : on débraye directement', 'L’éclairage seulement'], e: 'Diaporama : couper l’alimentation de la machinerie (la force uniquement) en laissant la lumière.', s: 'mode' },
    { q: 'Après le dégagement, l’appareil est :', c: ['Laissé hors service', 'Remis en service', 'Testé par un voyage à vide', 'Rappelé au rez-de-chaussée'], e: 'Le local est refermé en laissant l’appareil hors service ; la société d’ascenseur est demandée.', s: 'mode' },
    { q: 'Un ascenseur hydraulique :', c: ['N’a pas de contrepoids', 'A toujours un contrepoids', 'Équipe surtout les IGH', 'Fonctionne sans moteur électrique'], e: 'Diaporama : piston alimenté par une pompe à moteur électrique ; plus lent, sans contrepoids, courses d’environ 18 m maximum.', s: 'principes' },
    { q: 'Qui décide de faire sortir les victimes ?', c: ['Le chef d’agrès', 'L’équipier en machinerie', 'Les victimes elles-mêmes', 'Le technicien ascensoriste par téléphone'], e: 'Diaporama : le chef d’agrès décide de faire sortir la ou les victimes.', s: 'mode' },
    { q: 'La commande d’appel prioritaire pompiers s’active :', c: ['Par le carré de la polycoise ou une clé de l’exploitant', 'Par un code donné par le CODIS', 'Automatiquement à l’alarme', 'Depuis la cabine'], e: 'Livret p. 54.', s: 'prioritaire' }
  ]
});

/* ================================================================ 8. PAO */
VSAV.chap({
  id: 'inc-pao', part: 'inc', seq: INC9,
  title: 'La prévention appliquée à l’opération (PAO)', short: 'PAO', motif: 'clip',
  sources: [L5 + ', § 2.7 La prévention appliquée à l’opération, p. 52-54', 'Diaporama « La PAO » (SDIS 51)', 'Guide d’instruction et de manœuvre INC — la prévention appliquée à l’opération (bâtiments d’habitation)'],
  summary: 'Prévention, prévision et moyens de secours : reconnaître sur le terrain ce qui facilite l’intervention.',
  why: '<b>Pourquoi un équipier doit-il connaître la prévention ?</b> Pas pour faire un cours de réglementation : pour <b>repérer et utiliser</b> sur place ce que le bâtiment met à sa disposition (colonne sèche, désenfumage, baie accessible, ascenseur prioritaire, SSI…). Un moyen connu fait gagner des minutes ; un moyen ignoré reste inutile.',
  sections: [
    { id: 'definitions', t: 'Prévention et prévision', ic: 'book', src: L5 + ', § 2.7 § 1, p. 52 ; diaporama « La PAO », diapos 3-4',
      html: '<div class="tw"><table><thead><tr><th></th><th>Objet</th><th>Exemples</th></tr></thead><tbody><tr><td><b>Prévention</b></td><td>Éviter la naissance d’un incendie et, s’il se produit, en limiter les effets.</td><td>Dégagements, BAES, désenfumage, portes coupe-feu, matériaux, plans d’évacuation…</td></tr><tr><td><b>Prévision</b></td><td>Mieux appréhender les risques et informer les SP pour organiser vite un dispositif adapté.</td><td>Cartographie opérationnelle, contrôle des PEI, plans d’ÉTAblissements RÉpertoriés (ÉTARE), études des zones, plans locaux d’urbanisme.</td></tr></tbody></table></div>' +
        '<p><b>Objectifs de la prévention</b> : éviter la naissance d’un incendie ; limiter sa propagation ; assurer une évacuation sûre et rapide du public ; <b>faciliter l’intervention des secours</b>.</p>' },
    { id: 'mesures', t: 'Les mesures essentielles', ic: 'list', src: L5 + ', § 2.7, p. 52',
      html: '<div class="tw"><table><thead><tr><th>Pour…</th><th>Mesures</th></tr></thead><tbody><tr><td>La sécurité des personnes</td><td>Alarme ; dégagements (nombre, largeur en unités de passage) ; éclairage (balisage, ambiance) ; désenfumage.</td></tr><tr><td>La protection des biens</td><td>Construction (solidité, réaction au feu, compartimentage, isolement) ; installations techniques ; moyens de secours ; consignes et plan d’intervention.</td></tr><tr><td><b>L’intervention des SP</b></td><td>Moyen d’alerte ; voies engins / voies échelle ; BI et PI ; colonnes sèches ou en charge (humides) ; plans d’intervention et d’évacuation ; désenfumage ; éclairage de sécurité ; ascenseurs prioritaires ; tours d’incendie (théâtres) ; trémies d’attaque (magasins) ; raccords ZAG ; extinction automatique.</td></tr></tbody></table></div>' +
        '<p><b>Outils facilitant l’action des SP</b> (diaporama) : <b>baie accessible</b> en façade (marquée par un <b>point rouge</b>), ventilation mécanique (skydome), personne ressource de l’entreprise (membre de l’ESI…), plan de situation et SSI indiquant le lieu exact de l’alarme, ascenseur prioritaire.</p>',
      figs: [{ img: 'img/inc/5/plan-evacuation.jpg', cap: 'Plan d’évacuation', txt: '<p>Il situe le lecteur (« vous êtes ici »), les cheminements, les moyens de secours et le point de rassemblement : une aide précieuse pour orienter une reconnaissance.</p>', src: 'Diaporama « La PAO » (SDIS 51)' }] },
    { id: 'moyens', t: 'Les moyens de secours en détail', ic: 'list', src: L5 + ', § 2.7, p. 53-54',
      html: '<p>Moyens fixes ou mobiles : extincteurs, <b>RIA</b>, extinction automatique, déversoirs, couvertures, bacs à sable ; alarme interne ; <b>SSI</b> ; alerte des secours ; service de sécurité incendie (SSIAP) ; poste de sécurité ; dispositifs facilitant l’intervention.</p>' +
        '<ul class="check"><li><b>RIA</b> (robinet d’incendie armé) : équipement de premier secours alimenté en eau en permanence, prêt à l’emploi (tuyau sous eau mais pas sous pression), utilisable par un personnel qualifié ou non, en attendant les secours.</li><li><b>SSI</b> (système de sécurité incendie) : collecte, traite et exécute les fonctions de mise en sécurité du bâtiment : détecter l’incendie et mettre en sécurité automatiquement ou sur action humaine.</li><li><b>Extinction automatique à eau</b> (sprinkleurs) : têtes sur canalisations sous pression ; l’ampoule se rompt ou le fusible fond à température anormale ; la circulation d’eau actionne une <b>cloche hydraulique</b> au poste de contrôle (renvoi au poste de sécurité). Aucune intervention humaine n’est nécessaire.</li></ul>',
      figs: [{ img: 'img/inc/5/ssi.jpg', cap: 'Les éléments d’un SSI', txt: '<p>Déclencheurs manuels et détecteurs automatiques informent le tableau de signalisation, qui commande diffuseurs sonores et dispositifs de mise en sécurité (ventouses électromagnétiques des portes).</p>', src: 'Diaporama « La PAO » (SDIS 51)' }] },
    { id: 'habitations', t: 'Les bâtiments d’habitation (familles)', ic: 'grid', src: 'Guide d’instruction et de manœuvre INC — PAO, bâtiments d’habitation (arrêté du 31 janvier 1986)',
      html: '<div class="tw"><table><thead><tr><th>Famille</th><th>Bâtiments</th><th>Moyens mis à disposition (guide)</th></tr></thead><tbody><tr><td><b>1<sup>re</sup></b></td><td>Individuelles isolées ou jumelées R+1 au plus ; RDC groupées en bande ; R+1 en bande à structures indépendantes</td><td>DECI définie au RDDECI</td></tr><tr><td><b>2<sup>e</sup></b></td><td>Individuelles &gt; R+1 ou en bande (cas cités) ; collectives R+3 au plus</td><td>Collectif ≤ 8 m : escalier à l’abri des fumées, une façade accessible à l’échelle à coulisse ; &gt; 8 m : escalier encloisonné et désenfumé ou à l’air libre</td></tr><tr><td><b>3<sup>e</sup> A</b></td><td>Plancher bas du logement le plus haut ≤ 28 m ; R+7 au plus ; porte palière la plus éloignée à ≤ 7 m de l’escalier (≤ 10 m depuis 2015) ; accès aux escaliers atteints par la voie échelle</td><td>Voie échelle sur la façade desservie par les escaliers ; escalier encloisonné et désenfumé ou à l’air libre</td></tr><tr><td><b>3<sup>e</sup> B</b></td><td>Ne satisfait pas la 3<sup>e</sup> A ; accès aux escaliers à moins de 50 m d’une voie</td><td>Escalier encloisonné et désenfumé ou à l’air libre, désenfumage des circulations, colonne sèche possible (PEI à 60 m)</td></tr><tr><td><b>4<sup>e</sup></b></td><td>Plancher bas du logement le plus haut entre 28 et 50 m</td><td>Escalier encloisonné et désenfumé ou à l’air libre, désenfumage des circulations, <b>colonne sèche</b> ; 1 PI à 100 m de l’accès et 1 PI à 60 m de la colonne sèche ; pas de voie échelle</td></tr></tbody></table></div>' +
        '<p>Au-delà de 50 m (ou avec des locaux non d’habitation), le bâtiment est un <b>IGH</b>. Points de vigilance du guide : présence de personnes vulnérables et de nuit ; logements non contrôlés (stockage) ; <b>limites de la PAO</b> : colonnes sèches et portes palières dégradées, communs encombrés, accès gênés par stationnement et jardins ; attention aux constructions d’avant 1986, aux gaines techniques et aux constructions en bois. Point positif : au moins un détecteur de fumée (DAAF) par logement depuis 2015. Principe d’action : <b>confinement</b> des impliqués dans leur logement et évacuation des logements touchés.</p>' }
  ],
  key: ['Prévention : éviter le feu et en limiter les effets ; prévision : préparer l’intervention.', 'Objectifs : éviter, limiter la propagation, évacuer, faciliter les secours.', 'Baie accessible en façade = point rouge.', 'RIA : sous eau en permanence mais pas sous pression.', 'Sprinkleur : ampoule ou fusible, cloche hydraulique, sans intervention humaine.', 'Ascenseur prioritaire : carré de polycoise ou clé de l’exploitant.', 'Habitations : principe de confinement, évacuation des logements touchés.'],
  traps: ['Confondre prévention (le bâtiment) et prévision (la préparation des secours : ÉTARE, PEI, cartographie).', 'Se fier aveuglément aux équipements : colonnes sèches ou portes palières peuvent être dégradées.'],
  quiz: [
    { q: 'Les plans ÉTARE relèvent de :', c: ['La prévision', 'La prévention', 'La PTI', 'La réhabilitation'], e: 'Diaporama PAO : la prévision comprend la création et la mise à jour des plans d’ÉTAblissements RÉpertoriés.', s: 'definitions' },
    { q: 'Comment est signalée une baie accessible sur une façade d’immeuble ?', c: ['Par un point rouge', 'Par un triangle jaune', 'Par une bande verte', 'Par une croix blanche'], e: 'Diaporama PAO, outils facilitant l’action des SP.', s: 'mesures' },
    { q: 'Un RIA est dit « armé » car :', c: ['Il est alimenté en permanence et prêt à l’emploi', 'Il est sous pression permanente', 'Il est réservé aux pompiers', 'Il possède une lance à mousse'], e: 'Livret p. 53 : tuyau sous eau mais pas sous pression.', s: 'moyens' },
    { q: 'Le déclenchement d’une tête de sprinkleur :', c: ['Se fait seul, par rupture de l’ampoule ou fonte du fusible', 'Nécessite l’action du gardien', 'Se fait depuis le SSI uniquement', 'Est commandé par les SP'], e: 'Livret p. 54 : aucun besoin d’intervention humaine ; cloche hydraulique au poste de contrôle.', s: 'moyens' },
    { q: 'Quel n’est PAS un objectif de la prévention ?', c: ['Rechercher les causes de l’incendie', 'Éviter la naissance d’un incendie', 'Limiter la propagation', 'Faciliter l’intervention des secours'], e: 'La recherche des causes relève de la RCCI, soutenue par la préservation des traces et indices.', s: 'definitions' },
    { q: 'Un bâtiment d’habitation de 4e famille est équipé :', c: ['D’une colonne sèche dans l’escalier', 'D’une voie échelle obligatoire', 'De sprinkleurs dans chaque logement', 'D’aucun moyen particulier'], e: 'Guide d’instruction : colonne sèche, escalier protégé, désenfumage des circulations ; absence de voie échelle.', s: 'habitations' }
  ]
});

/* ================================================================ 9. Protection, déblai, surveillance, PTI */
VSAV.chap({
  id: 'inc-deblai', part: 'inc', seq: INC9,
  title: 'Protection, déblai, surveillance et préservation des traces et indices', short: 'Déblai et surveillance', motif: 'target',
  sources: [L5 + ', § 2.8 (renvoi au GDO Incendies de structures, p. 80-83)', 'GDO Incendies de structures (2018), § 6 à 11, p. 80-83', 'Guide d’instruction et de manœuvre INC — MGO : protection, déblai, surveillance, PTI, matériel de déblai'],
  summary: 'Protéger les biens dès le début, déblayer sans détruire les indices, surveiller jusqu’à l’extinction complète.',
  why: '<b>Pourquoi le déblai est-il dangereux ?</b> Le feu semble fini, la vigilance baisse, la fatigue monte, l’ARI pèse… alors que fumées toxiques, structures fragilisées et risque électrique sont toujours là. Le GDO le qualifie de <b>phase accidentogène</b>. Déblayer trop, en plus, efface les indices qui expliqueront l’origine du feu.',
  sections: [
    { id: 'protection', t: 'La protection', ic: 'shield', src: 'GDO 2018, § 6, p. 80-81',
      html: '<p>Les actions de protection évitent des conséquences autres que celles du feu : <b>économiques</b> (arrêt d’activité) et <b>psychologiques</b> (perte d’un élément de mémoire collective ou privée).</p>' +
        '<ul class="check"><li><b>Protéger de quoi ?</b> Des effets directs du feu et des fumées, mais aussi des effets de la lutte : <b>dégâts des eaux</b>, conséquences des <b>coupures de fluides</b>.</li><li><b>Quels biens ?</b> Valeur financière, patrimoniale, historique, artistique, sentimentale, et objets dont la perte complique le retour à la normale (<b>clés, papiers administratifs, justificatifs</b>, fichiers clients, comptabilité…).</li><li><b>Environnement</b> : gérer les eaux d’extinction (confinement, récupération), les effluents gazeux (rideaux d’eau, qui génèrent eux-mêmes des effluents liquides), mesurer les polluants.</li><li><b>Comment ?</b> Sur la cible (déplacer les biens, isoler les captages d’eau potable) ou sur le flux (<b>bâchage</b>, endiguement, assèchement, ventilation dès les premières phases).</li></ul>' +
        '<div class="callout warn"><b>Protéger quand ?</b> « Quand l’eau ruisselle sur les biens à protéger, il est déjà trop tard. » La question se pose au COS <b>dès le début</b> de l’intervention, parfois avant l’extinction (œuvres d’art).</div>' },
    { id: 'deblai', t: 'Le déblai', ic: 'flame', src: 'GDO 2018, § 7, p. 81 ; Guide d’instruction INC — le matériel de déblai, exemple de flash fire',
      html: '<p>Les déblais <b>facilitent l’extinction</b> et <b>éliminent les risques de reprise</b> du feu.</p>' +
        '<div class="callout bad"><b>Phase accidentogène :</b> les risques persistent (ambiance toxique, effondrement, risque électrique, blessures) alors que la vigilance baisse (fatigue, désengagement d’une partie des moyens, difficulté à porter l’ARI).</div>' +
        '<ul class="check"><li>Des mesures de toxiques peuvent être faites ponctuellement ou en continu (appareils individuels ou balises) ; la protection respiratoire peut alors être <b>adaptée</b>, mais le dispositif de protection doit être <b>évalué et maintenu</b>.</li><li>La recherche peut être complétée par le <b>détecteur CO</b>.</li><li>La connaissance des matériaux et modes de construction oriente les choix techniques.</li><li><b>Des déblais trop poussés</b> rendent très difficile l’expertise judiciaire et la recherche des causes : il est souhaitable que le déblai soit entrepris après échange entre le COS, un officier formé à la RCCI s’il existe, l’OPJ, voire l’autorité judiciaire, le propriétaire, l’assureur. Les SDIS orientent soit vers des déblais, soit vers des <b>déblais modérés et une surveillance accrue</b>.</li></ul>' +
        '<p><b>Outils de forcement et de déblai</b> (guide) : gaffe, hachette, balai de cantonnier, pelle, pioche, fourche droite et fourche recourbée.</p>' +
        '<p><b>Exemple du guide</b> : feu de chambre éteint vite sans refroidissement des matériaux ; ils continuent de pyrolyser et une poche de gaz s’accumule au plafond. En sortant un matelas contenant des braises, l’équipe apporte l’énergie d’activation : la poche s’enflamme (flash fire).</p>' },
    { id: 'surveillance', t: 'La surveillance', ic: 'eye', src: 'GDO 2018, § 8 et 9, p. 81-82 ; Guide d’instruction INC',
      html: '<p>La surveillance s’assure de l’<b>absence de reprise de feu</b> et que des <b>tiers ne s’exposent pas</b> aux risques avant que sinistrés ou services municipaux n’aient mis en place protections et avertissements. Le <b>gardiennage n’est pas une mission des SDIS</b>, mais le COS éclaire les sinistrés (à défaut l’autorité locale) sur les mesures à prendre.</p>' +
        '<ul class="check"><li>Elle est effectuée <b>en continu</b> sur le site, avec des moyens capables de répondre à toute évolution défavorable.</li><li>En situation courante, l’<b>absence de point chaud vérifiée pendant 2 heures</b> peut permettre au COS de considérer le feu comme totalement éteint.</li><li>Ne pas sous-estimer les risques d’accident (chute, blessure, brûlure) ni d’exposition aux toxiques (air, surfaces souillées).</li></ul>' +
        '<div class="callout warn"><b>Avant de quitter les lieux</b>, gaz de pyrolyse (potentiellement inflammables) et gaz de combustion (potentiellement toxiques) sont <b>systématiquement recherchés</b> dans toute la structure. Une fumée blanche inexpliquée par l’extinction est le signe d’une pyrolyse (une fumée <b>jaunâtre</b> en est un indicateur plutôt fiable) ; même expliquée par l’extinction, une fumée blanche n’est pas sans risque.</div>' +
        '<p><b>Relogement</b> : de la responsabilité du DOS ; le COS l’informe au plus tôt quand un logement est inutilisable (fumées, suies, stabilité, absence d’énergies).</p>' },
    { id: 'pti', t: 'La préservation des traces et indices (PTI)', ic: 'eye', src: 'GDO 2018, § 11, p. 83 ; Guide d’instruction INC',
      html: '<p>Trois objectifs :</p><ul class="check"><li>identifier comment le feu a <b>débuté et s’est propagé</b> (déclenchement précoce des processus assurantiel, voire juridique, au bénéfice des sinistrés et victimes) ;</li><li>identifier les <b>comportements ou équipements à risque</b> (éducation des populations, évolution des technologies) ;</li><li>alimenter le <b>retour d’expérience</b> des sapeurs-pompiers.</li></ul>' +
        '<p>La preuve pénale s’appuie de plus en plus sur la preuve technique ou scientifique, déduite des traces et indices. La scène peut être dégradée par le feu, mais aussi par les intervenants, les témoins, les sinistrés… La PTI vise donc à <b>limiter l’altération et la contamination</b> de la scène ; elle repose sur l’<b>observation et la mémorisation</b>, le <b>déblai temporisé et/ou adapté</b>.</p>' +
        '<ul class="check"><li>Elle est d’autant plus efficace qu’elle est <b>précoce</b>, par le COS et les équipes engagées, dans la mesure où elle ne nuit pas à la qualité des secours.</li><li>Certains SIS disposent de sapeurs-pompiers investigateurs (<b>RCCI</b> : recherche des causes et circonstances d’incendie).</li><li>Si le déblai nécessaire à l’extinction va détruire des éléments, les <b>recueillir en amont</b> dans la mesure du possible.</li></ul>' }
  ],
  key: ['Protéger dès le début : quand l’eau ruisselle, il est trop tard.', 'Déblai = phase accidentogène : risques présents, vigilance en baisse.', 'Déblai trop poussé = expertise des causes compromise.', 'Pas de point chaud pendant 2 h : le COS peut considérer le feu éteint (situation courante).', 'Avant de partir : rechercher gaz de pyrolyse et de combustion dans toute la structure.', 'Fumée jaunâtre = indicateur plutôt fiable de pyrolyse.', 'PTI : observer, mémoriser, déblai temporisé ou adapté.', 'Le gardiennage n’est pas une mission des SDIS.'],
  traps: ['Retirer l’ARI dès que les flammes ont disparu.', 'Tout sortir et tout gratter « pour être sûr » : les indices disparaissent.', 'Interpréter toute fumée blanche comme de la simple vapeur d’eau.'],
  quiz: [
    { q: 'Selon le GDO, en situation courante, le COS peut considérer le feu totalement éteint après :', c: ['2 heures sans point chaud vérifié', '30 minutes de surveillance', 'Le départ du dernier engin', '24 heures'], e: 'GDO 2018 § 8, p. 81.', s: 'surveillance' },
    { q: 'Pourquoi le déblai est-il qualifié de phase accidentogène ?', c: ['Les risques persistent alors que la vigilance des intervenants diminue', 'Il se fait toujours de nuit', 'Il n’utilise aucun outil', 'Il est réalisé par des renforts non formés'], e: 'GDO 2018 § 7 : ambiance toxique, effondrement, électricité… alors que fatigue et baisse de vigilance s’installent.', s: 'deblai' },
    { q: 'Quand se pose la question de la protection des biens ?', c: ['Dès le début de l’intervention', 'Après l’extinction', 'Pendant le déblai seulement', 'Au retour au centre'], e: '« Quand l’eau ruisselle sur les biens à protéger, il est déjà trop tard. »', s: 'protection' },
    { q: 'Une fumée jaunâtre persiste après extinction. Elle indique plutôt :', c: ['Une pyrolyse en cours', 'De la vapeur d’eau sans danger', 'La fin de l’incendie', 'Une fuite d’eau'], e: 'GDO § 9 : une fumée jaunâtre est un indicateur plutôt fiable de la pyrolyse.', s: 'surveillance' },
    { q: 'La préservation des traces et indices repose notamment sur :', c: ['L’observation, la mémorisation et un déblai temporisé ou adapté', 'Un déblai complet et rapide', 'La photographie par les témoins', 'L’intervention exclusive de la police'], e: 'GDO § 11.', s: 'pti' },
    { q: 'Le gardiennage des lieux après incendie :', c: ['N’est pas une mission des SDIS ; le COS conseille sinistrés ou autorité locale', 'Est assuré par le dernier binôme', 'Est assuré par le VSAV', 'Est obligatoire pendant 48 h'], e: 'GDO § 8.', s: 'surveillance' },
    { q: 'Parmi ces biens, lequel le GDO cite-t-il comme prioritaire pour le retour à la normale des sinistrés ?', c: ['Clés et documents administratifs', 'Le mobilier de jardin', 'Les revêtements de sol', 'Les matériaux de toiture'], e: 'GDO § 6.2 : objets dont la perte complique la vie des sinistrés (clés, papiers, justificatifs…).', s: 'protection' }
  ]
});

/* ================================================================ 10. Réhabilitation POP-32 */
VSAV.chap({
  id: 'inc-rehabilitation', part: 'inc', seq: INC9,
  title: 'Réhabilitation après incendie : POP-32', short: 'Réhabilitation (POP-32)', motif: 'spray',
  sources: ['POP-32 SDIS 51 — Protocole de réhabilitation suite à un incendie (indice 01, 03-02-2023)', 'GDO Incendies de structures (2018), § 10, p. 82'],
  summary: 'Trois niveaux de souillure, cinq protocoles : se déséquiper sans emporter les suies dans l’engin ni chez soi.',
  why: '<b>Pourquoi se « décontaminer » après un simple feu ?</b> Les suies et dépôts des fumées sont toxiques : ils passent des EPI à la peau, puis à la cabine de l’engin et au centre. Le protocole fixe un <b>zonage</b> et un <b>ordre de retrait</b> qui coupent cette chaîne de transfert, adapté au niveau de souillure.',
  sections: [
    { id: 'principe', t: 'Principe et dotation', ic: 'list', src: 'POP-32, p. 1',
      html: '<p>Le protocole repose sur <b>plusieurs niveaux de souillure</b> par les fumées et les suies ; il permet la réhabilitation et le reconditionnement du personnel et des matériels engagés.</p>' +
        '<div class="tw"><table><thead><tr><th>Caisse « décontamination »</th><th>FPT / CCRM</th><th>CCF / FMOGP / MEA</th></tr></thead><tbody><tr><td>Sacs hydrosolubles</td><td>1 rouleau de 20</td><td>1 rouleau de 10</td></tr><tr><td>Gants de toilette à usage unique pré-savonnés</td><td>50</td><td>25</td></tr><tr><td>Masques FFP3</td><td>6</td><td>4</td></tr><tr><td>Lunettes de protection</td><td>6 paires</td><td>4 paires</td></tr><tr><td>Brosses</td><td>2</td><td>1</td></tr><tr><td colspan="3">Et : 1 drap papier à usage unique, 1 boîte de gants vinyle, 1 tenue papier type 5, 1 rouleau de sacs-poubelle blancs, 1 marqueur noir (marquage nominatif des sacs d’effets personnels).</td></tr></tbody></table></div>' +
        '<p>Tenues de rhabillage sous plastique en cabine (FPT/CCRM : 6 polaires, 6 bonnets, 6 polos). Le <b>CRCP</b> est dimensionné pour <b>20 personnels</b> (kits individuels avant passage, gants de toilette en 1<sup>re</sup> cabine, kits de rhabillage en 2<sup>e</sup> cabine).</p>' },
    { id: 'niveaux', t: 'Trois niveaux, cinq protocoles', ic: 'grid', src: 'POP-32, p. 2-3',
      html: '<div class="tw"><table><thead><tr><th>Niveau</th><th>Souillure</th><th>Exemples</th><th>Protocole</th></tr></thead><tbody><tr><td><b>I</b></td><td>Superficielle, sans nettoyage à l’eau (poussières, dépôts secs)</td><td>Aliment laissé sur le feu, feu extérieur, feu de végétaux</td><td>1</td></tr><tr><td><b>II</b></td><td>Superficielle, nécessitant un nettoyage à l’eau et/ou odeur persistante</td><td>Feu de chambre, feu de VL</td><td>2</td></tr><tr><td><b>III</b></td><td>Importante, nettoyage à l’eau (dépôts gras, produits chimiques)</td><td>Feu d’entrepôt, intervention d’ampleur</td><td>3a : désengagement provisoire<br>3b : définitif sans CRCP<br>3c : définitif avec CRCP</td></tr></tbody></table></div>',
      figs: [{ img: 'img/inc/5/pop32-niveaux.jpg', cap: 'Niveaux de souillure et protocoles', txt: '<p>Le niveau III se décline selon que le désengagement est provisoire (3a) ou définitif, sans (3b) ou avec (3c) le CRCP.</p>', src: 'POP-32 SDIS 51, p. 2' }] },
    { id: 'protocole1', t: 'Protocole 1 (niveau I)', ic: 'check', src: 'POP-32, p. 3',
      html: '<p>Souillure superficielle ne nécessitant pas de nettoyage à l’eau.</p>',
      steps: ['Définir un zonage opérationnel : zone d’exclusion, zone contrôlée, zone de soutien.', 'Sortir la caisse « décontamination » et mettre en place un drap unique en zone contrôlée.', 'Si besoin, habiller un nettoyeur (personnel « propre ») : tenue papier type 5, masque FFP2, lunettes, gants vinyle.', 'Dans cet ordre : retirer le masque ARI, le casque et la cagoule, puis s’équiper d’un masque FFP2 et de lunettes.', 'Auto-brossage à sec des gants et de la tenue, du haut vers le bas (ou brossage par le nettoyeur).', 'Retirer gants, veste textile et surpantalon.', 'Auto-nettoyage des zones exposées (mains, visage, cou) avec les gants de toilette à usage unique.', 'Le nettoyeur met drap et déchets en poubelle ordinaire et se déséquipe.', 'Retirer FFP2 et lunettes une fois la décontamination finalisée, objets contaminés isolés.'], stepsTitle: 'Protocole 1' },
    { id: 'protocole2', t: 'Protocole 2 (niveau II) et protocole 3b', ic: 'drop', src: 'POP-32, p. 3-4',
      html: '<p>Le protocole 2 (souillure superficielle nécessitant l’eau) et le protocole 3b (niveau III, désengagement définitif sans CRCP) suivent la même trame ; en 3b, ARI, matériels et tenues contaminés peuvent aussi être pris en charge par un <b>VTU</b> prévu à cet effet.</p>',
      steps: ['Définir le zonage : exclusion, contrôlée, soutien.', 'Sortir la caisse « décontamination », drap unique en zone contrôlée.', 'Si besoin, habiller un nettoyeur (tenue type 5, FFP2, lunettes, gants vinyle).', 'Dans cet ordre : retirer masque ARI, casque, gants et cagoule, puis s’équiper de FFP2, lunettes et gants vinyle.', 'Retirer dossard ARI, veste textile et surpantalon.', 'Placer la tenue de feu (cagoule, pantalon, veste, gants textiles) dans un sac hydrosoluble.', 'Isoler ARI et matériels contaminés dans le coffre arrière du véhicule.', 'Après retrait des gants vinyle, auto-nettoyage des mains, du visage et du cou (gants de toilette à usage unique).', 'Mise en poubelle du drap et des déchets par le nettoyeur, qui se déséquipe.', 'Retirer le FFP2 une fois la décontamination terminée et tout objet contaminé isolé.', 'Percevoir une tenue de rhabillage (restituée ensuite au CIS).', 'Au retour au CIS : nettoyage des tenues en machines spécifiques EPI.', 'Dans la mesure du possible : douche, changement de TSI (ou tenue F1) et restauration avant retour en disponibilité.'], stepsTitle: 'Protocole 2' },
    { id: 'protocole3', t: 'Protocoles 3a et 3c', ic: 'team', src: 'POP-32, p. 4-6',
      html: '<p><b>3a — désengagement provisoire :</b> après le retrait des EPI dans un <b>parc matériel</b> et l’auto-nettoyage, le personnel reçoit une tenue de rhabillage et accède à la <b>zone de soutien sanitaire et ravitaillement</b>. Retour opérationnel dans l’ordre : « déséquipement du maillage propre », FFP2 et gants vinyle, rhabillage textile et dossard ARI laissés au parc matériel, retrait du FFP2 et des gants <b>le plus tard possible</b>.</p>' +
        '<p><b>3c — désengagement définitif avec CRCP :</b> dossards ARI pris en charge par VTU ou isolés ; présentation au CRCP ; kit individuel (casque et effets personnels dans des sacs distincts fermés ; vestes, surpantalons, gants et cagoules souillés dans les grandes caisses) ; surbottes, puis retrait FFP2 et gants avant d’entrer ; auto-nettoyage et retrait du polo en cabine ; kit de rhabillage en cabine suivante ; zone de soutien. Les tenues partent chez le prestataire (pôle logistique du CHU de Reims ou CH de Châlons) ; au CIS, nettoyage des chaussants et du casque sous FFP2 et gants vinyle ; tenues à récupérer <b>dans les 48 h</b> après dépôt.</p>',
      figs: [{ img: 'img/inc/5/pop32-crcp.jpg', cap: 'Schéma du protocole 3c au CRCP', txt: '<p>De la zone d’exclusion (forte contamination) vers la zone de soutien : pose de l’ARI et équipement FFP2 à l’engin, dépôt des textiles sales et des sacs d’effets, passage dans la cellule sanitaire (auto-nettoyage, puis rhabillage), retour au centre.</p>', src: 'POP-32 SDIS 51, p. 6' }] },
    { id: 'gdo', t: 'Ce que dit le GDO 2018 (et les écarts)', ic: 'book', src: 'GDO 2018, § 10, p. 82',
      html: '<p>Le GDO préconise un nettoyage maximum des EPI et matériels <b>sur les lieux</b>, pour limiter tout transfert dans le véhicule, selon 4 options choisies par le COS : pas de nettoyage nécessaire ; brossage léger à sec (brosse à poils doux), complété si besoin par un rinçage léger en jet diffusé au débit minimum avec la lance du dévidoir tournant ; brossage à l’eau savonneuse si dépôts gras ; sinon <b>emballage</b> des EPI et matériels avant de rejoindre la zone de soutien.</p>' +
        '<p>Il ajoute un <b>lavage systématique des mains et des effets chaussants</b> avant de réintégrer le véhicule.</p>' +
        '<div class="callout warn"><b>Divergences entre sources :</b> le GDO 2018 décrit 4 options de nettoyage, la POP-32 (plus récente, SDIS 51) 3 niveaux et 5 protocoles. Le GDO prévoit que le déshabillage soit réalisé par des sapeurs-pompiers protégés (FFP3, masque à cartouche filtrante ou ARI) ; la POP-32 équipe nettoyeur et personnels de <b>masques FFP2</b> dans ses étapes, alors que la caisse de dotation qu’elle décrit contient des <b>masques FFP3</b>. Appliquez la consigne de votre encadrement.</div>' }
  ],
  key: ['3 niveaux de souillure, 5 protocoles (1, 2, 3a, 3b, 3c).', 'Toujours : zonage exclusion / contrôlée / soutien et drap unique en zone contrôlée.', 'Ordre de retrait : masque ARI, casque, (gants), cagoule, puis FFP2 et lunettes.', 'Tenue de feu dans un sac hydrosoluble ; ARI et matériels isolés au coffre arrière.', 'Auto-nettoyage mains, visage, cou avec gants de toilette à usage unique.', 'FFP2 retiré en dernier, une fois tout objet contaminé isolé.', 'CRCP : 20 personnels ; tenues récupérées sous 48 h.'],
  traps: ['Remonter en cabine avec la veste souillée.', 'Retirer sa protection respiratoire avant d’avoir isolé les objets contaminés.', 'Mélanger effets personnels et tenues souillées.'],
  quiz: [
    { q: 'Un feu de chambre correspond, selon la POP-32, au niveau :', c: ['II', 'I', 'III', 'Aucun nettoyage'], e: 'POP-32 : niveau II, superficiel nécessitant un nettoyage à l’eau (ex. feu de chambre, feu de VL).', s: 'niveaux' },
    { q: 'Combien de protocoles la POP-32 décline-t-elle ?', c: ['5', '3', '4', '2'], e: '1, 2, 3a, 3b, 3c.', s: 'niveaux' },
    { q: 'Dans le protocole 2, où place-t-on la tenue de feu ?', c: ['Dans un sac hydrosoluble', 'Dans la cabine de l’engin', 'Dans un sac d’effets personnels', 'Sur le drap, pour séchage'], e: 'POP-32 : cagoule, pantalon, veste, gants textiles dans un sac hydrosoluble.', s: 'protocole2' },
    { q: 'Le protocole 3c s’applique :', c: ['Au niveau III, désengagement définitif avec CRCP', 'Au niveau III, désengagement provisoire', 'Au niveau II avec CRCP', 'Au niveau I'], e: '3a provisoire ; 3b définitif sans CRCP ; 3c définitif avec CRCP.', s: 'niveaux' },
    { q: 'Quelles zones du corps sont auto-nettoyées avec les gants de toilette ?', c: ['Mains, visage, cou', 'Pieds et jambes', 'Dos uniquement', 'Aucune : douche au centre'], e: 'POP-32 : zones exposées (mains, visage, cou).', s: 'protocole1' },
    { q: 'Avant de réintégrer le véhicule, le GDO impose :', c: ['Un lavage systématique des mains et des effets chaussants', 'Une douche complète sur place', 'Le port de l’ARI', 'Un rinçage de la cabine'], e: 'GDO 2018 § 10, p. 82.', s: 'gdo' },
    { q: 'Quand retire-t-on le masque FFP2 ?', c: ['Une fois la décontamination terminée et les objets contaminés isolés', 'Dès la sortie du feu', 'Avant de retirer le casque', 'Au retour au centre seulement'], e: 'POP-32, dernière étape des protocoles 1 et 2.', s: 'protocole1' }
  ]
});

